PAGES_DATA = [{'page_no': 1, 'title': 'Sherlock Holmes and the Walking Stick', 'tr_title': 'Sherlock Holmes ve Yürüyüş Bastonu', 'vocab_focus': [('stick', 'baston'), ('examine', 'incelemek, muayene etmek'), ('deduction', 'tümdengelem, akıl yürütme'), ('engraving', 'oyma yazı, kabartma'), ('gratitude', 'minnettarlık, şükran'), ('specimen', 'örnek, numune'), ('companion', 'yoldaş, arkadaş'), ('modest', 'alçakgönüllü, mütevazı')], 'sentences': [{'id': 1, 'text': 'Mr. Sherlock Holmes was sitting at the breakfast table in our sitting room at Baker Street.', 'translation': "Bay Sherlock Holmes, Baker Sokağı'ndaki oturma odamızda kahvaltı masasında oturuyordu.", 'notes': 'was sitting: Past Continuous (oturuyordu).'}, {'id': 2, 'text': 'I was standing upon the hearth-rug and picked up the walking stick which our visitor had left behind the night before.', 'translation': 'Ben şömine kiliminin üzerinde duruyordum ve önceki gece gelen ziyaretçimizin arkasında bıraktığı yürüyüş bastonunu elime aldım.', 'notes': 'had left behind: Past Perfect Tense (geride bırakmıştı).'}, {'id': 3, 'text': 'It was a fine, thick piece of wood with a bulbous head, of the kind which is known as a Penang lawyer.', 'translation': "Tokmak başlı, 'Penang avukatı' olarak bilinen türden, kalın ve kaliteli bir tahta parçasıydı.", 'notes': 'is known as: Passive Voice (olarak bilinir).'}, {'id': 4, 'text': 'Just under the head was a broad silver band nearly an inch across.', 'translation': 'Başlığın hemen altında yaklaşık bir inç genişliğinde gümüş bir şerit vardı.', 'notes': 'just under: tam altında.'}, {'id': 5, 'text': "Upon this silver band were engraved the words: 'To James Mortimer, M.R.C.S., from his friends of the C.C.H., 1884.'", 'translation': "Bu gümüş halkanın üzerine şu sözler kazınmıştı: 'C.C.H.'deki dostlarından James Mortimer'a, 1884.'", 'notes': 'were engraved: oyulmuştu / kazınmıştı (Passive).'}, {'id': 6, 'text': '"Well, Watson, what do you make of it?" asked Holmes, leaning back in his chair.', 'translation': '"Pekâlâ Watson, bundan ne çıkarıyorsun?" diye sordu Holmes, koltuğuna yaslanarak.', 'notes': 'what do you make of it: bundan ne anlıyorsun / nasıl yorumluyorsun?'}, {'id': 7, 'text': 'He had his back turned to me, and I had given no sign of what I was doing.', 'translation': 'Sırtı bana dönüktü ve ne yaptığıma dair en ufak bir işaret vermemiştim.', 'notes': 'had given no sign: hiç işaret vermemiştim.'}, {'id': 8, 'text': '"How did you know what I was doing? I believe you have eyes in the back of your head!"', 'translation': '"Ne yaptığımı nereden bildin? İnanıyorum ki başının arkasında bile gözlerin var!"', 'notes': 'eyes in the back of your head: deyim (her şeyi gören gözler).'}, {'id': 9, 'text': '"I have, at least, a very well-polished silver-plated coffee pot in front of me," he said with a smile.', 'translation': '"En azından önümde gayet iyi parlatılmış gümüş kaplama bir cezve var," dedi gülümseyerek.', 'notes': 'silver-plated: gümüş kaplama.'}, {'id': 10, 'text': '"Tell me, Watson, what do you deduce about the owner of that stick?"', 'translation': '"Söyle bana Watson, o bastonun sahibi hakkında ne gibi bir akıl yürütmede bulunuyorsun?"', 'notes': 'deduce: çıkarım yapmak, akıl yürütmek.'}, {'id': 11, 'text': '"I think," I answered, following Holmes\'s methods, "that Dr. Mortimer is a successful elderly medical man."', 'translation': '"Bence," diye yanıtladım Holmes\'un yöntemlerini izleyerek, "Doktor Mortimer saygın ve yaşlıca bir tıp doktoru."', 'notes': 'following: izleyerek (Participle).'}, {'id': 12, 'text': '"The letters C.C.H. probably stand for a local hunt, whose members presented him with this gift."', 'translation': '"C.C.H. harfleri muhtemelen, üyelerinin kendisine bu hediyeyi sunduğu yerel bir av kulübünü temsil ediyor."', 'notes': 'stand for: anlamına gelmek, temsil etmek.'}, {'id': 13, 'text': 'Holmes took the stick from my hands and examined it with his naked eyes.', 'translation': 'Holmes bastonu ellerimden aldı ve çıplak gözleriyle dikkatle inceledi.', 'notes': 'naked eyes: çıplak göz.'}, {'id': 14, 'text': 'Then he lit a cigarette and walked over to the window with a magnifying glass.', 'translation': 'Ardından bir sigara yaktı ve elinde bir büyüteçle pencerenin kenarına doğru yürüdü.', 'notes': 'magnifying glass: büyüteç.'}, {'id': 15, 'text': '"Interesting, though elementary," said he, inspecting the marks upon the wood.', 'translation': '"İlginç, ama son derece basit," dedi ahşap üzerindeki izleri incelerken.', 'notes': 'elementary: temel, basit.'}, {'id': 16, 'text': '"I would suggest that C.C.H. stands for Charing Cross Hospital in London."', 'translation': '"Bence C.C.H., Londra\'daki Charing Cross Hastanesi\'ni temsil ediyor."', 'notes': 'would suggest: ileri sürmek, belirtmek.'}, {'id': 17, 'text': '"And Dr. Mortimer was probably a young house-surgeon who left the hospital to practice in the country."', 'translation': '"Ve Doktor Mortimer muhtemelen taşrada hekimlik yapmak üzere hastaneden ayrılmış genç bir asistandı."', 'notes': 'house-surgeon: hastane asistan hekimi.'}, {'id': 18, 'text': '"How can you tell that he is a country doctor?" I asked in astonishment.', 'translation': '"Onun taşra doktoru olduğunu nasıl anlayabiliyorsun?" diye sordum hayretle.', 'notes': 'in astonishment: hayret içerisinde.'}, {'id': 19, 'text': '"Observe the bottom of the stick; it is worn down by walking miles over rough country roads."', 'translation': '"Bastonun ucuna bak; çetin köy yollarında miller boyu yürünerek aşınmış durumda."', 'notes': 'worn down: aşınmış, yıpranmış.'}, {'id': 20, 'text': '"Furthermore, look at these tooth marks; our country doctor clearly owns a curly-haired spaniel."', 'translation': '"Dahası, şu diş izlerine bak; taşra doktorumuzun kıvırcık tüylü bir av köpeği olduğu gün gibi aşikâr."', 'notes': 'furthermore: dahası, üstelik.'}]}, {'page_no': 2, 'title': 'Dr. Mortimer Arrives at 221B Baker Street', 'tr_title': "Dr. Mortimer'nin 221B Baker Sokağı'na Gelişi", 'vocab_focus': [('visitor', 'ziyaretçi'), ('spectacles', 'gözlük'), ('enthusiast', 'tutkulu kimse, meraklı'), ('skull', 'kafatası'), ('fascinating', 'büyüleyici, son derece çekici'), ('manuscript', 'el yazması belge'), ('extraordinary', 'olağanüstü, sıra dışı'), ('legend', 'efsane, rivayet')], 'sentences': [{'id': 21, 'text': 'At that very moment, there was a sharp ring at the front bell, followed by steps upon the stairs.', 'translation': 'Tam o anda dış kapının zili sertçe çaldı ve ardından merdivenlerde ayak sesleri duyuldu.', 'notes': 'followed by: ardından gelen.'}, {'id': 22, 'text': 'The door opened, and our visitor entered the room exactly as Holmes had predicted.', 'translation': "Kapı açıldı ve ziyaretçimiz tıpkı Holmes'un tahmin ettiği şekilde içeri girdi.", 'notes': 'as predicted: tahmin edildiği gibi.'}, {'id': 23, 'text': 'He was a very tall, thin man, with a long nose and grey eyes behind gold-rimmed spectacles.', 'translation': 'Altın çerçeveli gözlüklerinin ardından bakan gri gözleri ve uzun burnuyla çok uzun boylu, zayıf bir adamdı.', 'notes': 'gold-rimmed: altın çerçeveli.'}, {'id': 24, 'text': 'In his hand he carried the very spaniel that Holmes had described only seconds earlier.', 'translation': "Kucağında, Holmes'un sadece birkaç saniye önce tarif ettiği av köpeğini taşıyordu.", 'notes': 'the very spaniel: tam da o av köpeği.'}, {'id': 25, 'text': '"I am Dr. James Mortimer, of Grimpen, in Dartmoor, Devon," he said, bowing politely to us.', 'translation': '"Ben Devon, Dartmoor\'daki Grimpen\'den Doktor James Mortimer," dedi ve bize kibarca başıyla selam verdi.', 'notes': 'bowing politely: kibarca eğilerek selam verme.'}, {'id': 26, 'text': '"Glad to meet you, sir," said Holmes, shaking his hand warmly.', 'translation': '"Sizinle tanıştığıma memnun oldum efendim," dedi Holmes, elini samimiyetle sıkarak.', 'notes': 'shaking hand warmly: elini sıcakça sıkmak.'}, {'id': 27, 'text': '"I observe that your coat has seen hard service, and your fingers show a passion for science."', 'translation': '"Görüyorum ki paltonuz epey yıpranmış ve parmaklarınız bilime olan derin tutkunuzu gösteriyor."', 'notes': 'has seen hard service: çok kullanılmış/yıpranmış.'}, {'id': 28, 'text': '"Indeed, Mr. Holmes, I am an enthusiast in anthropology and comparative skull anatomy,"', 'translation': '"Gerçekten de öyle Bay Holmes; antropolojiye ve karşılaştırmalı kafatası anatomisine büyük merakım var,"', 'notes': 'enthusiast: meraklı, tutkun.'}, {'id': 29, 'text': '"Your own skull, if I may say so, is a splendid specimen for any scientific museum."', 'translation': '"Şunu söylemeliyim ki sizin kafatasınız herhangi bir bilim müzesi için mükemmel bir numune olurdu."', 'notes': 'splendid specimen: muhteşem bir örnek.'}, {'id': 30, 'text': 'Holmes laughed quietly and motioned Dr. Mortimer to take an armchair by the fire.', 'translation': "Holmes hafifçe güldü ve Dr. Mortimer'a şöminenin yanındaki koltuğa oturmasını işaret etti.", 'notes': 'motioned to: oturmasını işaret etti.'}, {'id': 31, 'text': '"I presume, Doctor, that you did not come to London merely to examine my skull."', 'translation': '"Tahmin ediyorum ki Doktor, Londra\'ya sadece benim kafatasımı incelemek için gelmediniz."', 'notes': 'merely: yalnızca, sadece.'}, {'id': 32, 'text': '"No, indeed, Mr. Holmes! I come because I am in urgent need of your expert advice."', 'translation': '"Hayır, asla Bay Holmes! Sizin uzman tavsiyenize son derece acil ihtiyacım olduğu için geldim."', 'notes': 'urgent need: acil ihtiyaç.'}, {'id': 33, 'text': '"A most singular and terrible problem has occurred in our quiet neighbourhood in Dartmoor."', 'translation': '"Dartmoor\'daki sakin çevremizde son derece tuhaf ve korkunç bir olay meydana geldi."', 'notes': 'singular: eşsiz, olağandışı, tuhaf.'}, {'id': 34, 'text': 'Dr. Mortimer reached into his inner pocket and drew out a folded, yellowed paper.', 'translation': 'Dr. Mortimer iç cebine uzandı ve katlanmış, sararmış bir kağıt çıkardı.', 'notes': 'yellowed: sararmış (zamanla).'}, {'id': 35, 'text': '"I have in my pocket a manuscript dated 1742, which has been preserved in the Baskerville family."', 'translation': '"Cebimde, Baskerville ailesinde nesiller boyu saklanmış, 1742 tarihli bir el yazması var."', 'notes': 'has been preserved: muhafaza edilmiştir (Passive).'}, {'id': 36, 'text': '"It was given to me by my dear friend, Sir Charles Baskerville, who died three months ago."', 'translation': '"Bu belge bana üç ay önce vefat eden sevgili dostum Sir Charles Baskerville tarafından verilmişti."', 'notes': 'who died: Relative Clause (vefat eden).'}, {'id': 37, 'text': '"His tragic death caused a great sensation throughout the whole county of Devonshire."', 'translation': '"Onun trajik ölümü bütün Devonshire kontluğunda büyük bir yankı uyandırdı."', 'notes': 'caused a great sensation: büyük sansasyon/yankı yarattı.'}, {'id': 38, 'text': '"The public believed it was a sudden heart attack, but I know there was something far worse."', 'translation': '"Halk bunun ani bir kalp krizi olduğuna inandı, fakat ben çok daha korkunç bir şey olduğunu biliyorum."', 'notes': 'far worse: çok daha kötü.'}, {'id': 39, 'text': '"Before I speak of his death, I must read this old manuscript concerning the family curse."', 'translation': '"Onun ölümünden bahsetmeden önce, aile lanetine dair bu eski el yazmasını okumalıyım."', 'notes': 'concerning: ...e dair, ile ilgili.'}, {'id': 40, 'text': 'Holmes leaned back, closed his eyes, and prepared himself to listen with keen attention.', 'translation': 'Holmes arkasına yaslandı, gözlerini kapattı ve derin bir dikkatle dinlemeye hazırlandı.', 'notes': 'keen attention: pürdikkat, keskin ilgi.'}]}, {'page_no': 3, 'title': 'The Legend of Hugo Baskerville', 'tr_title': 'Hugo Baskerville Efsanesi ve Lanetin Doğuşu', 'vocab_focus': [('ancestor', 'ata, soy'), ('wicked', 'kötü kalpli, ahlaksız'), ('maiden', 'genç kız, bakire'), ('captive', 'tutsak, esir'), ('fury', 'öfke, hiddet'), ('hound', 'tazı, av köpeği'), ('throat', 'boğaz, gırtlak'), ('curse', 'lanet, beddua')], 'sentences': [{'id': 41, 'text': 'Dr. Mortimer adjusted his glasses and began to read the ancient eighteenth-century script.', 'translation': 'Dr. Mortimer gözlüklerini düzeltti ve on sekizinci yüzyıldan kalma kadim metni okumaya başladı.', 'notes': 'ancient script: kadim yazı/metin.'}, {'id': 42, 'text': '"During the Great Rebellion, Hugo Baskerville was the lord of the manor of Baskerville Hall."', 'translation': '"Büyük İsyan döneminde Hugo Baskerville, Baskerville Malikanesi\'nin efendisiydi."', 'notes': 'lord of the manor: malikane beyi/efendisi.'}, {'id': 43, 'text': '"He was a wild, profane, and godless man who lived without honour or moral law."', 'translation': '"Onur ya da ahlak tanımayan; çılgın, küfürbaz ve inançsız bir adamdı."', 'notes': 'profane: kutsala saygısız.'}, {'id': 44, 'text': '"This Hugo conceived a dark passion for the daughter of a modest farmer near the estate."', 'translation': '"Bu Hugo, arazinin yakınlarındaki mütevazı bir çiftçinin kızına karşı karanlık bir tutku besledi."', 'notes': 'conceived a passion: tutkuya kapılmak.'}, {'id': 45, 'text': '"The maiden feared his wicked reputation and avoided him whenever he rode across the moor."', 'translation': '"Genç kız onun kötü şöhretinden korkuyor ve Hugo bataklıkta at sürdüğünde ondan kaçıyordu."', 'notes': 'wicked reputation: kötü nam.'}, {'id': 46, 'text': '"On Michaelmas night, Hugo and his evil companions kidnapped the girl and locked her in an upper room."', 'translation': '"Mikail Yortusu gecesinde, Hugo ve kötü niyetli arkadaşları kızı kaçırıp üst kattaki bir odaya kilitlediler."', 'notes': 'kidnapped: kaçırdılar.'}, {'id': 47, 'text': '"While the men drank wine and sang drunken songs downstairs, the terrified girl climbed down the ivy."', 'translation': '"Adamlar aşağıda şarap içip sarhoş naraları atarken, dehşete düşen kız sarmaşıklara tutunarak aşağı indi."', 'notes': 'ivy: sarmaşık.'}, {'id': 48, 'text': '"She fled across the dark moor toward her father\'s farm, three miles away through the fog."', 'translation': '"Sisin içinden üç mil uzaktaki babasının çiftliğine doğru karanlık bataklık boyunca kaçtı."', 'notes': 'fled: kaçtı (flee fiilinin geçmiş hali).'}, {'id': 49, 'text': '"When Hugo discovered her escape, he raged like a madman and summoned his hounds."', 'translation': '"Hugo onun kaçtığını anlayınca bir deli gibi öfkelendi ve tazılarını çağırttı."', 'notes': 'raged like a madman: çılgına döndü.'}, {'id': 50, 'text': '"He swore to the devil that he would give his body and soul to overtake the girl that very night."', 'translation': '"O gece kıza yetişmek uğruna bedenini ve ruhunu şeytana adayacağına yemin etti."', 'notes': 'swore: yemin etti (swear).'}, {'id': 51, 'text': '"Mounted upon his black mare, Hugo galloped into the darkness, following the crying hounds."', 'translation': '"Siyah kısrağına binen Hugo, uluyan tazıların peşinden karanlığa doğru dörtnala at sürdü."', 'notes': 'black mare: siyah kısrak.'}, {'id': 52, 'text': '"His companions rode behind him, laughing and shouting, until they reached a deep hollow on the moor."', 'translation': '"Arkadaşları gülüp bağırarak arkasından sürdüler, ta ki bataklıktaki derin bir çukura varana dek."', 'notes': 'deep hollow: derin çöküntü / vadi.'}, {'id': 53, 'text': '"There they found the poor maiden lying dead upon the grass, killed by pure terror and exhaustion."', 'translation': '"Orada zavallı kızı otların üstünde, saf dehşet ve yorgunluktan can vermiş halde yatarken buldular."', 'notes': 'lying dead: ölü yatarken.'}, {'id': 54, 'text': '"But worse than that, standing over Hugo Baskerville was a foul and monstrous creature."', 'translation': '"Fakat bundan daha korkuncu, Hugo Baskerville\'in üzerinde dikilen iğrenç ve devasa bir yaratıktı."', 'notes': 'monstrous: canavarımsı, korkunç devasa.'}, {'id': 55, 'text': '"It was a great black beast, shaped like a hound, yet larger than any hound that ever walked the earth."', 'translation': '"Tazı biçiminde devasa siyah bir hayvandı, fakat dünyada yürümüş hiçbir tazıdan çok daha büyüktü."', 'notes': 'shaped like: biçiminde.'}, {'id': 56, 'text': '"Even as they watched, the monstrous hound tore the throat out of Hugo Baskerville."', 'translation': '"Onlar dehşetle bakarken bile, bu devasa tazı Hugo Baskerville\'in gırtlağını parçalayarak kopardı."', 'notes': 'tore out: parçalayarak söktü.'}, {'id': 57, 'text': '"It turned its blazing eyes upon the men, and they shrieked and rode for their lives in terror."', 'translation': '"Ateş saçan gözlerini adamlara çevirdi; adamlar çığlıklar atarak can havliyle kaçtılar."', 'notes': 'blazing eyes: kor gibi parlayan gözler.'}, {'id': 58, 'text': '"One died that very night of the fright, and the others were broken men for the rest of their days."', 'translation': '"Biri o gece korkudan öldü, diğerleri ise hayatlarının geri kalanında ruhen çökmüş birer adam oldular."', 'notes': 'broken men: yıkılmış / perişan adamlar.'}, {'id': 59, 'text': '"Such is the tale of the hound that has plagued our family ever since with sudden and bloody deaths."', 'translation': '"O günden beri ailemize ani ve kanlı ölümlerle musallat olan tazının hikayesi işte böyledir."', 'notes': 'has plagued: musallat olmuştur.'}, {'id': 60, 'text': '"The manuscript warns all sons of Baskerville never to cross the moor in the dark hours of night."', 'translation': '"El yazması, Baskerville\'in tüm evlatlarını gecenin karanlık saatlerinde bataklığa ayak basmamaları için uyarır."', 'notes': 'warns to: ...maması konusunda uyarır.'}]}, {'page_no': 4, 'title': 'The Death of Sir Charles Baskerville', 'tr_title': "Sir Charles Baskerville'ın Esrarengiz Ölümü", 'vocab_focus': [('baronet', 'baronet (İngiliz soyluluk unvanı)'), ('alley', 'yürüyüş yolu, çitli yol'), ('nervous', 'gergin, tedirgin'), ('dread', 'dehşet, yılgı'), ('wicket-gate', 'küçük bahçe kapısı'), ('ash', 'kül'), ('footprint', 'ayak izi'), ('coroner', 'adli tıp yetkilisi, sorgu hakimi')], 'sentences': [{'id': 61, 'text': 'When Dr. Mortimer finished reading, Holmes yawned and tossed his cigarette end into the grate.', 'translation': 'Dr. Mortimer okumayı bitirdiğinde Holmes esnedi ve sigarasının izmaritini şömine ızgarasına fırlattı.', 'notes': 'tossed: fırlattı.'}, {'id': 62, 'text': '"A fairy tale, Dr. Mortimer, fit only to amuse children," Holmes remarked casually.', 'translation': '"Bir peri masalı Dr. Mortimer, sadece çocukları eğlendirmeye yarar," diye belirtti Holmes kayıtsızca.', 'notes': 'fit only to: yalnızca ...e yarar.'}, {'id': 63, 'text': '"To you it may seem a legend, Mr. Holmes, but to Sir Charles Baskerville it was a deadly reality."', 'translation': '"Size bir efsane gibi gelebilir Bay Holmes, fakat Sir Charles Baskerville için ölümcül bir gerçekti."', 'notes': 'deadly reality: ölümcül gerçeklik.'}, {'id': 64, 'text': '"Sir Charles was an elderly gentleman who made a massive fortune in South African gold mines."', 'translation': '"Sir Charles, Güney Afrika altın madenlerinde devasa bir servet kazanmış yaşlı bir beyefendiydi."', 'notes': 'massive fortune: devasa servet.'}, {'id': 65, 'text': '"Two years ago, he returned to Devonshire to restore the ancestral hall and help the local poor."', 'translation': '"İki yıl önce ata yadigarı malikaneyi onarmak ve yerel yoksullara yardım etmek için Devonshire\'a döndü."', 'notes': 'restore: onarmak, ihya etmek.'}, {'id': 66, 'text': '"He was widely loved for his generosity, but his nervous system was completely shattered by fear."', 'translation': '"Cömertliği nedeniyle herkes tarafından çok sevilirdi, fakat sinir sistemi korkudan tamamen çökmüştü."', 'notes': 'shattered: parçalanmış, mahvolmuş.'}, {'id': 67, 'text': '"He took this ancient legend to heart and genuinely believed that an evil doom hung over him."', 'translation': '"Bu eski efsaneyi yüreğinde hissetti ve üzerinde şeytani bir felaketin kol gezdiğine sahiden inandı."', 'notes': 'took to heart: ciddiye aldı / dert etti.'}, {'id': 68, 'text': '"Nothing would induce him to go out upon the moor at night, no matter how bright the moon might be."', 'translation': '"Ay ne kadar parlak olursa olsun, hiçbir şey onu geceleyin bataklığa çıkmaya ikna edemezdi."', 'notes': 'no matter how: ne kadar ... olursa olsun.'}, {'id': 69, 'text': '"Yet every evening before retiring, he walked down the famous Yew Alley of Baskerville Hall to smoke a cigar."', 'translation': '"Yine de her akşam uyumadan önce bir puro içmek için Baskerville Malikanesi\'nin meşhur Porsuk Ağaçlı Yolunda yürürdü."', 'notes': 'retiring: yatmaya gitmek.'}, {'id': 70, 'text': '"The Yew Alley is a narrow path bordered by solid twelve-foot walls of dense yew hedges."', 'translation': '"Porsuk Ağaçlı Yol, sık porsuk ağaçlarından oluşan on iki ayaklık sert çitlerle çevrili dar bir patikadır."', 'notes': 'bordered by: ile sınırlandırılmış.'}, {'id': 71, 'text': '"On the night of the fourth of May, Sir Charles announced that he intended to leave for London the next morning."', 'translation': '"Dört Mayıs gecesi Sir Charles, ertesi sabah Londra\'ya gitme niyetinde olduğunu bildirdi."', 'notes': 'intended to: niyetindeydi.'}, {'id': 72, 'text': '"He went out for his usual evening stroll at nine o\'clock and never returned alive."', 'translation': '"Saat dokuzda her zamanki akşam yürüyüşüne çıktı ve bir daha asla canlı dönmedi."', 'notes': 'never returned alive: asla canlı dönmedi.'}, {'id': 73, 'text': '"At midnight, his butler, Mr. Barrymore, grew anxious and went out with a lantern to look for his master."', 'translation': '"Gece yarısı uşağı Bay Barrymore endişelendi ve elinde bir fenerle efendisini aramaya çıktı."', 'notes': 'grew anxious: endişelenmeye başladı.'}, {'id': 74, 'text': '"At the far end of the Yew Alley, near a small wicket-gate leading to the moor, he found the body."', 'translation': '"Porsuk Ağaçlı Yol\'un bataklığa açılan küçük bahçe kapısının yakınındaki en uç noktasında cesedi buldu."', 'notes': 'leading to: ...e çıkan / giden.'}, {'id': 75, 'text': '"Sir Charles lay face downwards on the gravel, his hands clutching the damp earth in agony."', 'translation': '"Sir Charles, elleri ızdırap içinde nemli toprağı kavramış vaziyette, çakılların üzerinde yüzüstü yatıyordu."', 'notes': 'clutching: sımsıkı kavrayarak.'}, {'id': 76, 'text': '"There was no physical wound or sign of violence anywhere upon the corpse."', 'translation': '"Cesedin üzerinde hiçbir fiziksel yara veya şiddet izi bulunmuyordu."', 'notes': 'sign of violence: şiddet izi.'}, {'id': 77, 'text': '"The medical report concluded that death was caused by cardiac exhaustion and long-standing heart disease."', 'translation': '"Tıbbi rapor, ölümün kalp yetmezliği ve uzun süredir var olan kalp rahatsızlığından kaynaklandığı sonucuna vardı."', 'notes': 'concluded that: sonucuna vardı.'}, {'id': 78, 'text': '"The coroner\'s inquest agreed, and the verdict satisfied the neighbours and the authorities."', 'translation': '"Adli soruşturma heyeti de onayladı ve karar komşuları ile yetkilileri tatmin etti."', 'notes': 'inquest: adli soruşturma.'}, {'id': 79, 'text': '"I myself inspected the scene within an hour of the discovery, before anyone else arrived."', 'translation': '"Başka hiç kimse gelmeden önce, cesedin bulunmasından bir saat içinde olay yerini bizzat inceledim."', 'notes': 'inspected the scene: olay yerini inceledi.'}, {'id': 80, 'text': '"And what did you see, Dr. Mortimer, that the police and the coroner failed to notice?" asked Holmes keenly.', 'translation': '"Peki polisin ve adli tabibin fark edemediği neyi gördünüz Dr. Mortimer?" diye sordu Holmes pürdikkat.', 'notes': 'failed to notice: fark edemedi.'}]}, {'page_no': 5, 'title': 'The Footprints of a Gigantic Hound', 'tr_title': 'Devasa Tazının Ayak İzleri', 'vocab_focus': [('whisper', 'fısıldamak'), ('gigantic', 'devasa, dev gibi'), ('boundary', 'sınır, sınır çizgisi'), ('tiptoe', 'ayak parmaklarının ucunda yürümek'), ('frightful', 'korkunç, ürkütücü'), ('distortion', 'bozulma, çarpılma'), ('supernatural', 'doğaüstü'), ('investigate', 'araştırmak, soruşturmak')], 'sentences': [{'id': 81, 'text': 'Dr. Mortimer leaned forward and lowered his voice to a terrified whisper.', 'translation': 'Dr. Mortimer öne doğru eğildi ve sesini dehşet dolu bir fısıltıya düşürdü.', 'notes': 'lowered his voice: sesini alçalttı.'}, {'id': 82, 'text': '"Mr. Holmes, the ground near the wicket-gate was soft and damp from the evening rain."', 'translation': '"Bay Holmes, bahçe kapısının yanındaki zemin akşam yağmuru sebebiyle yumuşak ve nemliydi."', 'notes': 'damp from: ...den ötürü nemli.'}, {'id': 83, 'text': '"Sir Charles had evidently stood by the gate for five to ten minutes, as proved by the cigar ash."', 'translation': '"Puro külünün kanıtladığı üzere Sir Charles besbelli kapının yanında beş ila on dakika beklemişti."', 'notes': 'evidently: besbelli, açıkça.'}, {'id': 84, 'text': '"Then he had started to run down the alley, and his footprints completely changed."', 'translation': '"Sonra yol boyunca koşmaya başlamıştı ve ayak izleri tamamen değişmişti."', 'notes': 'had started: koşmaya başlamıştı.'}, {'id': 85, 'text': '"Barrymore said he walked on tiptoe, but any man who runs runs on the balls of his feet!"', 'translation': '"Barrymore onun parmak ucunda yürüdüğünü söyledi, fakat koşan her insan tabanının ön kısmına basarak koşar!"', 'notes': 'balls of his feet: ayak tarağı / tabanın önü.'}, {'id': 86, 'text': '"He was fleeing for his life, running desperately away from something he saw at the gate."', 'translation': '"Canını kurtarmak için kaçıyordu; kapıda gördüğü şeyden delicesine uzaklaşmaya çalışıyordu."', 'notes': 'fleeing for his life: can havliyle kaçmak.'}, {'id': 87, 'text': '"And his face, Mr. Holmes, was contorted with such sheer horror that I could barely recognise him."', 'translation': '"Ve yüzü Bay Holmes, öylesine katıksız bir dehşetle çarpılmıştı ki onu güçlükle tanıyabildim."', 'notes': 'contorted: acıyla/dehşetle çarpılmış.'}, {'id': 88, 'text': '"Did you see any other marks upon the ground?" asked Holmes, his pipe forgotten in his fingers.', 'translation': '"Zeminde başka herhangi bir iz gördünüz mü?" diye sordu Holmes; piposu parmaklarının arasında unutulmuştu.', 'notes': 'forgotten: unutulmuş (Participle).'}, {'id': 89, 'text': '"No human footprints, none whatever," replied Mortimer slowly.', 'translation': '"Hiçbir insan ayak izi yoktu, kesinlikle hiç," diye yavaşça cevap verdi Mortimer.', 'notes': 'none whatever: kesinlikle hiç.'}, {'id': 90, 'text': '"A sheep? A pony? A cow?" asked Holmes with rising curiosity.', 'translation': '"Bir koyun mu? Midilli mi? Yoksa bir inek mi?" diye sordu Holmes artan bir merakla.', 'notes': 'rising curiosity: kabaran/artan merak.'}, {'id': 91, 'text': '"No, Mr. Holmes! Not sheep, not ponies, and not cows!"', 'translation': '"Hayır Bay Holmes! Ne koyun, ne midilli ve ne de inek!"', 'notes': 'neither nor yapısına benzer vurgu.'}, {'id': 92, 'text': '"Then what were they?" asked Holmes, leaning across the table.', 'translation': '"Öyleyse ne iziydi bunlar?" diye sordu Holmes masanın üzerine eğilerek.', 'notes': 'leaning across: masaya doğru eğilerek.'}, {'id': 93, 'text': '"Mr. Holmes, they were the footprints of a gigantic hound!"', 'translation': '"Bay Holmes, onlar devasa bir tazının ayak izleriydi!"', 'notes': 'gigantic hound: devasa tazı.'}, {'id': 94, 'text': 'A cold shiver ran down my spine as the doctor uttered those dreadful words.', 'translation': 'Doktor o korkunç sözleri söylerken sırtımdan aşağı soğuk bir ürperti indi.', 'notes': 'cold shiver: soğuk ürperti.'}, {'id': 95, 'text': '"A hound? You are certain? How large were the prints?" questioned Holmes.', 'translation': '"Bir tazı mı? Emin misiniz? İzler ne kadar büyüktü?" diye sorguladı Holmes.', 'notes': 'questioned: sorguladı.'}, {'id': 96, 'text': '"Enormous! Far larger than any ordinary dog in the kingdom could ever leave."', 'translation': '"Kocaman! Krallıktaki sıradan bir köpeğin bırakabileceğinden katbekat daha büyüktü."', 'notes': 'far larger: çok daha büyük.'}, {'id': 97, 'text': '"They were twenty yards away from the body, out on the moor grass, but clear and distinct."', 'translation': '"Cesetten yirmi yarda uzakta, bataklık otlarının üzerindeydiler; fakat net ve belirgindiler."', 'notes': 'clear and distinct: apaçık ve belirgin.'}, {'id': 98, 'text': '"The creature had not approached the body, but stood watching as the old man collapsed."', 'translation': '"Yaratık cesede yaklaşmamış, fakat yaşlı adam yere yığılırken durup izlemişti."', 'notes': 'collapsed: yere yığıldı.'}, {'id': 99, 'text': '"Several peasants on the moor claim to have seen a luminous, spectral beast wandering at night."', 'translation': '"Bataklıktaki birkaç köylü, geceleyin ortalıkta dolaşan ışık saçan, hayalet gibi bir canavar gördüklerini iddia ediyor."', 'notes': 'spectral beast: hayaletimsi canavar.'}, {'id': 100, 'text': '"They say it matches the description of the hound that slew Hugo Baskerville in 1742."', 'translation': '"1742 yılında Hugo Baskerville\'i katleden tazının tarifine birebir uyduğunu söylüyorlar."', 'notes': 'slew: katletti (slay fiilinin geçmişi).'}]}, {'page_no': 6, 'title': 'Sir Henry Baskerville Arrives from Canada', 'tr_title': "Sir Henry Baskerville'ın Kanada'dan Gelişi ve Kayıp Çizme", 'vocab_focus': [('heir', 'mirasçı, varis'), ('inherit', 'miras almak'), ('boot', 'çizme, bot'), ('hotel', 'otel'), ('unaccountable', 'açıklanamaz, akıl almaz'), ('tan', 'taba rengi, açık kahverengi'), ('vanish', 'ortadan kaybolmak'), ('perplexed', 'şaşkın, kafası karışmış')], 'sentences': [{'id': 101, 'text': '"Why did you not consult me immediately after the inquest?" Holmes asked severely.', 'translation': '"Adli soruşturmanın hemen ardından neden bana danışmadınız?" diye sordu Holmes sert bir tavırla.', 'notes': 'severely: sert bir şekilde.'}, {'id': 102, 'text': '"Because the matter is beyond the realm of human law, and I did not wish to seem superstitious,"', 'translation': '"Çünkü mesele insan yasalarının ötesindeydi ve batıl inançlı gibi görünmek istemedim,"', 'notes': 'beyond the realm: sınırlarının ötesinde.'}, {'id': 103, 'text': '"Then why do you come to me now? What has changed?" Holmes demanded.', 'translation': '"Öyleyse şimdi neden bana geldiniz? Değişen nedir?" diye sordu Holmes.', 'notes': 'demanded: sordu, talep etti.'}, {'id': 104, 'text': '"Sir Henry Baskerville, the nephew and sole surviving heir, arrives in London today from Canada."', 'translation': '"Sir Charles\'ın yeğeni ve hayatta kalan tek varisi olan Sir Henry Baskerville bugün Kanada\'dan Londra\'ya geliyor."', 'notes': 'sole surviving heir: hayatta kalan tek mirasçı.'}, {'id': 105, 'text': '"He inherits the estate and an income of nearly one million pounds sterling."', 'translation': '"Malikaneyi ve neredeyse bir milyon sterlinlik dev bir geliri miras alıyor."', 'notes': 'nearly: neredeyse, yaklaşık.'}, {'id': 106, 'text': '"Should I advise this young man to go to Baskerville Hall, or is it certain death for him?"', 'translation': '"Bu genç adama Baskerville Malikanesi\'ne gitmesini mi tavsiye etmeliyim, yoksa bu onun için kesin bir ölüm müdür?"', 'notes': 'certain death: kesin ölüm.'}, {'id': 107, 'text': '"Bring him here tomorrow morning at ten o\'clock," said Holmes decisively.', 'translation': '"Yarın sabah saat onda onu buraya getirin," dedi Holmes kararlı bir ses tonuyla.', 'notes': 'decisively: kesin ve kararlı şekilde.'}, {'id': 108, 'text': 'The next morning at ten, Dr. Mortimer returned, accompanied by Sir Henry Baskerville.', 'translation': 'Ertesi sabah saat onda Dr. Mortimer, yanında Sir Henry Baskerville ile geri döndü.', 'notes': 'accompanied by: eşliğinde.'}, {'id': 109, 'text': 'Sir Henry was a sturdy, dark-eyed young man of thirty, with an alert, weather-beaten face.', 'translation': 'Sir Henry; çevik, rüzgar ve güneşten yanmış yüzüyle otuz yaşlarında, sağlam yapılı, kara gözlü genç bir adamdı.', 'notes': 'weather-beaten: hava koşullarında yanmış/sertleşmiş.'}, {'id': 110, 'text': '"I am delighted to meet you, Mr. Holmes," said the young baronet with hearty Canadian openness.', 'translation': '"Sizinle tanıştığıma çok memnun oldum Bay Holmes," dedi genç baronet içten Kanada samimiyetiyle.', 'notes': 'hearty openness: içten açıklık.'}, {'id': 111, 'text': '"I would have sought your help even if Dr. Mortimer had not suggested this visit."', 'translation': '"Dr. Mortimer bu ziyareti önermemiş olsaydı bile yardımınıza başvuracaktım."', 'notes': 'would have sought: başvurmuş olacaktım.'}, {'id': 112, 'text': '"Something absurd and unaccountable happened to me at my hotel this very morning."', 'translation': '"Bu sabah otelimde başıma son derece saçma ve açıklanamaz bir olay geldi."', 'notes': 'unaccountable: izah edilemez.'}, {'id': 113, 'text': '"I bought a brand-new pair of brown boots yesterday on the Strand for six dollars."', 'translation': '"Dün Strand caddesinde altı dolara yepyeni bir çift kahverengi çizme satın aldım."', 'notes': 'brand-new pair: yepyeni bir çift.'}, {'id': 114, 'text': '"I put them outside my room to be polished, and this morning one of them was gone!"', 'translation': '"Boyanması için odamın dışına bıraktım ve bu sabah teki yok olmuştu!"', 'notes': 'was gone: kaybolmuştu / yoktu.'}, {'id': 115, 'text': '"Only one boot? Not the pair?" asked Holmes with a sudden flash of interest.', 'translation': '"Sadece tek bir çizme mi? İkisi birden değil mi?" diye sordu Holmes ani bir ilgi parıltısıyla.', 'notes': 'flash of interest: ani ilgi.'}, {'id': 116, 'text': '"Exactly! Just the right tan boot! The hotel staff searched everywhere, but found nothing."', 'translation': '"Aynen öyle! Yalnızca sağ taba rengi çizme! Otel personeli her yeri aradı ama hiçbir şey bulamadı."', 'notes': 'tan boot: taba rengi çizme.'}, {'id': 117, 'text': '"That is indeed most singular," muttered Holmes, rubbing his chin thoughtfully.', 'translation': '"Bu gerçekten çok tuhaf," diye mırıldandı Holmes, düşünceli bir şekilde çenesini sıvazlayarak.', 'notes': 'rubbing his chin: çenesini sıvazlayarak.'}, {'id': 118, 'text': '"Why would a thief steal a single brand-new boot that has never been worn?"', 'translation': '"Bir hırsız daha önce hiç giyilmemiş yepyeni tek bir çizmeyi neden çalsın ki?"', 'notes': 'has never been worn: hiç giyilmemiş (Present Perfect Passive).'}, {'id': 119, 'text': '"Perhaps it was merely misplaced by a careless servant," suggested Dr. Mortimer.', 'translation': '"Belki de dikkatsiz bir hizmetkar tarafından sadece yanlış bir yere konmuştur," diye öne sürdü Dr. Mortimer.', 'notes': 'misplaced: yanlış yere koyulmuş.'}, {'id': 120, 'text': '"Perhaps," said Holmes quietly, "but let us see if other strange things have occurred."', 'translation': '"Belki," dedi Holmes sakince, "fakat bakalım başka tuhaf şeyler de yaşanmış mı."', 'notes': 'let us see: görelim bakalım.'}]}, {'page_no': 7, 'title': 'The Warning Note from The Times', 'tr_title': 'The Times Gazetesinden Kesilmiş Uyarı Mektubu', 'vocab_focus': [('envelope', 'zarf'), ('warning', 'uyarı, ikaz'), ('paste', 'yapıştırmak'), ('headline', 'manşet, başlık'), ('scent', 'koku, parfüm'), ('scissors', 'makas'), ('counsel', 'öğüt, nasihat'), ('threat', 'tehdit')], 'sentences': [{'id': 121, 'text': '"There is another thing, Mr. Holmes, which is even stranger than the stolen boot,"', 'translation': '"Bir şey daha var Bay Holmes, çalınan çizmeden bile daha tuhaf,"', 'notes': 'even stranger: daha da tuhaf.'}, {'id': 122, 'text': 'Sir Henry took a rough grey envelope from his pocket and laid it upon the table.', 'translation': 'Sir Henry cebinden kaba gri bir zarf çıkardı ve masanın üzerine koydu.', 'notes': 'rough envelope: kaba zarf.'}, {'id': 123, 'text': "The address was written in clumsy printed letters: 'Sir Henry Baskerville, Northumberland Hotel.'", 'translation': "Adres acemice basılmış harflerle yazılmıştı: 'Sir Henry Baskerville, Northumberland Oteli.'", 'notes': 'printed letters: matbaa harfleri.'}, {'id': 124, 'text': '"It arrived this morning by the first post," explained the young baronet.', 'translation': '"Bu sabah ilk postayla geldi," diye açıkladı genç baronet.', 'notes': 'by the first post: ilk postayla.'}, {'id': 125, 'text': 'Inside was a single half-sheet of foolscap paper folded in four.', 'translation': 'İçinde dörde katlanmış yarım tabaka yazı kağıdı vardı.', 'notes': 'foolscap paper: dosya kağıdı.'}, {'id': 126, 'text': 'Across the middle of it a single sentence had been formed by pasting printed words upon the sheet.', 'translation': 'Sayfanın ortasına basılı sözcükler yapıştırılarak tek bir cümle oluşturulmuştu.', 'notes': 'had been formed: oluşturulmuştu (Past Perfect Passive).'}, {'id': 127, 'text': "The sentence read: 'As you value your life or your reason, keep away from the moor.'", 'translation': "Cümle şöyleydi: 'Hayatınıza veya aklınıza değer veriyorsanız, bataklıktan uzak durun.'", 'notes': 'as you value: değer veriyorsan.'}, {'id': 128, 'text': "Only the word 'moor' had been written in ink; all the other words were cut from a printed newspaper.", 'translation': "Yalnızca 'moor' (bataklık) sözcüğü mürekkeple yazılmıştı; diğer tüm kelimeler basılı bir gazeteden kesilmişti.", 'notes': 'cut from: ...den kesilmiş.'}, {'id': 129, 'text': '"Now, Mr. Holmes, what in heaven\'s name does this mean?" demanded Sir Henry.', 'translation': '"Şimdi söyler misiniz Bay Holmes, Allah aşkına bu ne anlama geliyor?" diye çıkıştı Sir Henry.', 'notes': "what in heaven's name: Allah aşkına ne."}, {'id': 130, 'text': '"It means, Sir Henry, that someone is watching you very closely in London," answered Holmes.', 'translation': '"Bunun anlamı Sir Henry, birisinin sizi Londra\'da çok yakından takip ettiğidir," diye yanıtladı Holmes.', 'notes': 'watching closely: yakından izlemek.'}, {'id': 131, 'text': 'Holmes picked up the paper and held it within an inch of his keen eyes.', 'translation': 'Holmes kağıdı aldı ve keskin gözlerinin bir inç yakınına kadar yaklaştırdı.', 'notes': 'held within: ... mesafede tuttu.'}, {'id': 132, 'text': '"These words were cut from yesterday\'s edition of The Times with short-bladed nail scissors."', 'translation': '"Bu sözcükler dünkü The Times gazetesinden kısa uçlu tırnak makasıyla kesilmiş."', 'notes': 'short-bladed: kısa uçlu.'}, {'id': 133, 'text': '"Notice the lead article on page four; the type and font match perfectly."', 'translation': '"Dördüncü sayfadaki başyazıya bakın; yazı tipi ve font kusursuz bir şekilde eşleşiyor."', 'notes': 'lead article: başyazı.'}, {'id': 134, 'text': '"The composer used gum and hurried work, as seen by the uneven alignment of the words."', 'translation': '"Mektubu hazırlayan kişi zamk kullanmış ve acele etmiş; kelimelerin hizasızlığından bu anlaşılıyor."', 'notes': 'uneven alignment: eğri büğrü hizalama.'}, {'id': 135, 'text': 'Holmes brought the paper close to his nose and sniffed it gently.', 'translation': 'Holmes kağıdı burnuna yaklaştırdı ve hafifçe kokladı.', 'notes': 'sniffed gently: hafifçe kokladı.'}, {'id': 136, 'text': '"There is a faint scent of white jessamine perfume upon the envelope," he murmured.', 'translation': '"Zarfın üzerinde belli belirsiz bir beyaz yasemin parfümü kokusu var," diye mırıldandı.', 'notes': 'faint scent: hafif/silik koku.'}, {'id': 137, 'text': '"That suggests a woman may have handled the paper or been present in the room."', 'translation': '"Bu da bir kadının kağıda dokunmuş ya da odada bulunmuş olabileceğini gösteriyor."', 'notes': 'may have handled: dokunmuş olabilir (Modal Perfect).'}, {'id': 138, 'text': '"Whoever sent this note intended it either as a mortal threat or as a desperate friendly warning."', 'translation': '"Bu notu her kim gönderdiyse, ya ölümcül bir tehdit ya da çaresiz bir dostane uyarı amacıyla göndermiş."', 'notes': 'either ... or: ya ... ya da.'}, {'id': 139, 'text': '"I have made up my mind," said Sir Henry with firm resolution.', 'translation': '"Kararımı verdim," dedi Sir Henry sarsılmaz bir kararlılıkla.', 'notes': 'made up my mind: karar verdim.'}, {'id': 140, 'text': '"No hound on earth or in hell will prevent me from going to the home of my ancestors!"', 'translation': '"Yeryüzündeki ya da cehennemdeki hiçbir tazı beni atalarımın evine gitmekten alıkoyamayacak!"', 'notes': 'prevent from: ...den alıkoymak.'}]}, {'page_no': 8, 'title': 'The Second Stolen Boot and the Shadowy Spy', 'tr_title': 'İkinci Çizmenin Çalınması ve Faytondaki Casus', 'vocab_focus': [('cab', 'fayton, kiralık araba'), ('beard', 'sakal'), ('shadow', 'gölge, takip etmek'), ('disguise', 'kılık değiştirme'), ('furious', 'küplere binmiş, aşırı öfkeli'), ('scoundrel', 'alçak, alık, düzenbaz'), ('cunning', 'kurnaz, sinsi'), ('pursuit', 'kovalama, takip')], 'sentences': [{'id': 141, 'text': 'As our visitors rose to leave, Holmes decided that we should secretly shadow them from a distance.', 'translation': 'Ziyaretçilerimiz gitmek için ayağa kalktığında Holmes onları uzaktan gizlice takip etmemiz gerektiğine karar verdi.', 'notes': 'shadow: gölge gibi takip etmek.'}, {'id': 142, 'text': 'We followed them down Regent Street at a discreet distance of fifty yards.', 'translation': 'Onları Regent Sokağı boyunca elli yardalık temkinli bir mesafeden izledik.', 'notes': 'discreet distance: dikkat çekmeyen mesafe.'}, {'id': 143, 'text': 'Suddenly, Holmes gripped my arm and pointed toward a hansom cab crawling along the curb.', 'translation': 'Aniden Holmes kolumu kavradı ve kaldırım boyunca yavaşça ilerleyen iki tekerlekli bir faytonu işaret etti.', 'notes': 'crawling along: yavaşça sürünür gibi gitmek.'}, {'id': 144, 'text': 'Inside the cab, a passenger with a bushy black beard was peering through the side glass at Sir Henry.', 'translation': "Faytonun içinde, gür siyah sakallı bir yolcu yan camdan Sir Henry'yi dikizliyordu.", 'notes': 'bushy black beard: gür kara sakal.'}, {'id': 145, 'text': '"There is our man, Watson! Quick, let us see his face before he moves!"', 'translation': '"İşte adamımız Watson! Çabuk, hareket etmeden yüzünü görelim!"', 'notes': 'there is our man: işte adamımız.'}, {'id': 146, 'text': 'At that very instant, the bearded stranger caught sight of Holmes and yelled an urgent order to the driver.', 'translation': "Tam o anda sakallı yabancı Holmes'u fark etti ve sürücüye aceleyle bir emir haykırdı.", 'notes': 'caught sight of: gözü ilişti / fark etti.'}, {'id': 147, 'text': 'The driver whipped the horse, and the cab galloped away furiously into the heavy traffic of Oxford Street.', 'translation': "Sürücü atı kamçıladı ve fayton hızla Oxford Sokağı'nın yoğun trafiğine dalarak uzaklaştı.", 'notes': 'whipped the horse: atı kamçıladı.'}, {'id': 148, 'text': '"Number 2704!" Holmes shouted, noting the license plate, but the vehicle was already lost from sight.', 'translation': '"Numara 2704!" diye bağırdı Holmes plakayı not ederek; fakat araç çoktan gözden kaybolmuştu.', 'notes': 'lost from sight: gözden kaybolmuş.'}, {'id': 149, 'text': '"A most cunning rogue!" Holmes exclaimed with a grim smile of professional admiration.', 'translation': '"Son derece kurnaz bir düzenbaz!" dedi Holmes mesleki bir takdirin getirdiği sert bir tebessümle.', 'notes': 'professional admiration: mesleki takdir.'}, {'id': 150, 'text': '"He recognized me immediately and escaped before I could corner him."', 'translation': '"Beni anında tanıdı ve ben onu köşeye sıkıştıramadan kaçtı."', 'notes': 'corner him: onu köşeye sıkıştırmak.'}, {'id': 151, 'text': "We walked directly to Sir Henry's hotel to warn him of the spy in the cab.", 'translation': "Faytondaki casus hakkında kendisini uyarmak için doğruca Sir Henry'nin oteline yürüdük.", 'notes': 'directly to: doğrudan ...e.'}, {'id': 152, 'text': 'We found Sir Henry in the hotel lobby, flushed red with sheer anger.', 'translation': "Sir Henry'yi otel lobisinde, katıksız bir öfkeden kıpkırmızı kesilmiş vaziyette bulduk.", 'notes': 'flushed red: öfkeden kızarmış.'}, {'id': 153, 'text': '"They have taken another of my boots!" he shouted, waving his arms in fury.', 'translation': '"Çizmelerimden bir başkasını daha almışlar!" diye haykırdı, kollarını öfkeyle savurarak.', 'notes': 'waving arms: kollarını sallamak.'}, {'id': 154, 'text': '"Not the new brown one, but an old black boot that I wore yesterday!"', 'translation': '"Yeni kahverengiyi değil, dün giydiğim eski siyah çizmelerden birini!"', 'notes': 'wore yesterday: dün giydiğim.'}, {'id': 155, 'text': "Holmes's eyes flashed with triumphant enlightenment at this unexpected news.", 'translation': "Bu beklenmedik haber karşısında Holmes'un gözleri zafer dolu bir aydınlanmayla parladı.", 'notes': 'triumphant enlightenment: muzaffer bir kavrayış.'}, {'id': 156, 'text': '"An old boot! That explains everything!" Holmes muttered under his breath.', 'translation': '"Eski bir çizme! Bu her şeyi açıklıyor!" diye mırıldandı Holmes kendi kendine.', 'notes': 'under his breath: fısıltıyla / kendi kendine.'}, {'id': 157, 'text': '"The new boot had no human scent upon the leather, so it was useless to the thief."', 'translation': '"Yeni çizmenin derisinde hiç insan kokusu yoktu; bu yüzden hırsızın hiçbir işine yaramadı."', 'notes': 'human scent: insan kokusu.'}, {'id': 158, 'text': '"He needed an old boot containing the unmistakable personal scent of Sir Henry Baskerville!"', 'translation': '"Sir Henry Baskerville\'in belirgin kişisel kokusunu taşıyan eski bir çizmeye ihtiyacı vardı!"', 'notes': 'unmistakable: şüphe götürmez, belirgin.'}, {'id': 159, 'text': '"Why would anyone want my personal scent?" asked Sir Henry, looking thoroughly bewildered.', 'translation': '"Biri benim kişisel kokumu neden istesin ki?" diye sordu Sir Henry, tamamen şaşkına dönmüş halde.', 'notes': 'thoroughly bewildered: büsbütün şaşırmış.'}, {'id': 160, 'text': '"To give a scent trail to a hound!" Holmes thought, though he kept the thought to himself for now.', 'translation': '"Bir tazıya koku izi vermek için!" diye düşündü Holmes, gerçi şimdilik bu düşünceyi kendine sakladı.', 'notes': 'scent trail: koku izi.'}]}, {'page_no': 9, 'title': 'Holmes Sends Watson to Dartmoor', 'tr_title': "Holmes'un Watson'ı Dartmoor'a Göndermesi", 'vocab_focus': [('entrust', 'emanet etmek, görevlendirmek'), ('revolver', 'altıpatlar, tabanca'), ('faithful', 'sadık, vefalı'), ('report', 'rapor, bildirmek'), ('watchful', 'uyanık, tetikte'), ('peril', 'büyük tehlike, tehlike'), ('investigation', 'soruşturma, araştırma'), ('presence', 'varlık, mevcudiyet')], 'sentences': [{'id': 161, 'text': "Sir Henry declared that he would take the two o'clock train to Devonshire on Saturday.", 'translation': "Sir Henry, Cumartesi günü saat ikideki trenle Devonshire'a gideceğini bildirdi.", 'notes': 'take the train: trene binmek.'}, {'id': 162, 'text': '"It is utterly impossible for me to leave London at present," said Holmes seriously.', 'translation': '"Şu anda Londra\'dan ayrılmam tamamen imkansız," dedi Holmes ciddiyetle.', 'notes': 'utterly impossible: tamamen imkansız.'}, {'id': 163, 'text': '"I am tied down by important matters of state which require my constant attention."', 'translation': '"Sürekli dikkatimi gerektiren mühim devlet meseleleri elimi kolumu bağlamış durumda."', 'notes': 'tied down: bağlanmış / meşgul.'}, {'id': 164, 'text': '"Yet you must not go to Baskerville Hall alone; danger lurks in every shadow."', 'translation': '"Yine de Baskerville Malikanesi\'ne tek başınıza gitmemelisiniz; her gölgede tehlike pusuya yatmış bekliyor."', 'notes': 'danger lurks: tehlike pusuya yatar.'}, {'id': 165, 'text': '"Who will accompany me, then?" asked Sir Henry, looking from Holmes to me.', 'translation': '"Öyleyse bana kim eşlik edecek?" diye sordu Sir Henry, bir Holmes\'a bir bana bakarak.', 'notes': 'accompany: eşlik etmek.'}, {'id': 166, 'text': '"Here is my faithful friend, Dr. Watson," said Holmes, placing a hand upon my shoulder.', 'translation': '"İşte sadık dostum Doktor Watson," dedi Holmes, elini omzuma koyarak.', 'notes': 'faithful friend: sadık dost.'}, {'id': 167, 'text': '"If he is willing to go, you could have no braver or more devoted companion in all England."', 'translation': '"Eğer gitmeye razı gelirse, bütün İngiltere\'de daha cesur ve daha vefalı bir yoldaş bulamazsınız."', 'notes': 'devoted companion: vefalı yol arkadaşı.'}, {'id': 168, 'text': '"I will gladly go!" I exclaimed without hesitation.', 'translation': '"Büyük bir memnuniyetle giderim!" diye haykırdım hiç tereddüt etmeden.', 'notes': 'without hesitation: tereddütsüz.'}, {'id': 169, 'text': '"Splendid!" cried Sir Henry warmly. "We will face whatever comes together, Doctor!"', 'translation': '"Mükemmel!" diye sevinçle bağırdı Sir Henry samimiyetle. "Bizi ne bekliyorsa birlikte göğüs gereceğiz Doktor!"', 'notes': 'face whatever comes: ne gelirse göğüs germek.'}, {'id': 170, 'text': 'Before we departed, Holmes took me aside into his private study for final instructions.', 'translation': 'Biz yola çıkmadan önce Holmes, son talimatları vermek üzere beni özel çalışma odasına çekti.', 'notes': 'took me aside: beni bir kenara çekti.'}, {'id': 171, 'text': '"Watson, keep your revolver in your pocket day and night, and never leave Sir Henry alone."', 'translation': '"Watson, tabancanı gece gündüz cebinde tut ve Sir Henry\'yi asla yalnız bırakma."', 'notes': 'revolver: altıpatlar tabanca.'}, {'id': 172, 'text': '"Do not attempt to formulate theories; simply report the facts to me as they happen."', 'translation': '"Teoriler üretmeye çalışma; sadece gerçekleri oluştukça bana rapor et."', 'notes': 'simply report: yalnızca rapor et.'}, {'id': 173, 'text': '"Observe the neighbours, the servants, and anyone who crosses your path upon the moor."', 'translation': '"Komşuları, hizmetkarları ve bataklıkta yolunuza çıkan herkesi dikkatle gözlemle."', 'notes': 'crosses your path: yolunuza çıkan.'}, {'id': 174, 'text': '"Pay special attention to Barrymore, the butler with the black beard who lives at the Hall."', 'translation': '"Malikanede yaşayan siyah sakallı uşak Barrymore\'a bilhassa çok dikkat et."', 'notes': 'pay special attention: özel dikkat göstermek.'}, {'id': 175, 'text': '"Could he be the man in the London cab? We must discover whether he was in Devon that day."', 'translation': '"Londra\'daki faytondaki adam o olabilir mi? O gün Devon\'da olup olmadığını ortaya çıkarmalıyız."', 'notes': 'could he be: o olabilir mi?'}, {'id': 176, 'text': '"I telegraphed to test his presence at Baskerville Hall, but the postmaster\'s boy was careless."', 'translation': '"Baskerville Malikanesi\'ndeki varlığını test etmek için telgraf çektim, ama postacının çırağı dikkatsiz davranmış."', 'notes': 'presence: mevcudiyet, bulunma.'}, {'id': 177, 'text': '"Therefore, the suspicion remains open and unresolved."', 'translation': '"Bu nedenle şüphe hâlâ ortada ve çözümsüz kalmış durumda."', 'notes': 'unresolved: çözülmemiş.'}, {'id': 178, 'text': '"Trust no one upon the moor, Watson, and keep your eyes open at every hour."', 'translation': '"Bataklıkta hiç kimseye güvenme Watson ve her saat gözlerini dört aç."', 'notes': 'keep eyes open: gözünü açık tutmak.'}, {'id': 179, 'text': 'I gripped my loaded revolver in my pocket, feeling the heavy responsibility upon my shoulders.', 'translation': 'Omuzlarımdaki ağır sorumluluğu hissederek cebimdeki dolu tabancamı kavradım.', 'notes': 'heavy responsibility: ağır mesuliyet.'}, {'id': 180, 'text': '"You may rely on me, Holmes; I will send you full and detailed reports of everything."', 'translation': '"Bana güvenebilirsin Holmes; sana her şeyin eksiksiz ve ayrıntılı raporlarını göndereceğim."', 'notes': 'rely on: güvenmek, bel bağlamak.'}]}, {'page_no': 10, 'title': 'Journey to Devonshire and the Escaped Convict', 'tr_title': 'Devonshire Yolculuğu ve Firari Mahkum Selden', 'vocab_focus': [('convict', 'mahkum, firari suçlu'), ('escape', 'kaçmak, firar etmek'), ('prison', 'hapishane'), ('moor', 'bozkır, funda bataklığı'), ('warder', 'gardiyan'), ('desperate', 'çaresiz, gözü dönmüş'), ('depot', 'istasyon, peron'), ('landscape', 'manzara, arazi')], 'sentences': [{'id': 181, 'text': 'Sir Henry, Dr. Mortimer, and I took our seats in a first-class carriage at Paddington Station.', 'translation': "Sir Henry, Dr. Mortimer ve ben Paddington İstasyonu'nda birinci mevki kompartımandaki yerlerimizi aldık.", 'notes': 'first-class carriage: birinci sınıf vagon.'}, {'id': 182, 'text': 'The train swept out of London, carrying us past green pastures and peaceful English villages.', 'translation': "Tren Londra'dan çıkıp hızlandı; bizi yemyeşil otlakların ve huzurlu İngiliz köylerinin yanından geçirdi.", 'notes': 'swept out: hızla çıkıp gitti.'}, {'id': 183, 'text': 'By late afternoon, the soft countryside transformed into a darker and bleaker terrain.', 'translation': 'İkindi vaktine doğru o yumuşak kırsal arazi yerini daha karanlık ve kasvetli bir coğrafyaya bıraktı.', 'notes': 'bleaker terrain: daha ıssız/kasvetli arazi.'}, {'id': 184, 'text': 'At last, we arrived at the small country station of Coombe Tracey on the edge of Dartmoor.', 'translation': "Nihayet Dartmoor'un kıyısındaki küçük Coombe Tracey kasaba istasyonuna vardık.", 'notes': 'on the edge of: kıyısında/kenarında.'}, {'id': 185, 'text': 'On the platform, two armed soldiers with rifles were standing watch by the gate.', 'translation': 'Peronda, tüfekli iki silahlı asker kapının yanında nöbet tutuyordu.', 'notes': 'standing watch: nöbet tutmak.'}, {'id': 186, 'text': 'A wagonette with two sturdy horses was waiting to carry us to Baskerville Hall.', 'translation': "Bizi Baskerville Malikanesi'ne götürmek üzere iki güçlü atın çektiği bir binek arabası bekliyordu.", 'notes': 'wagonette: binek arabası.'}, {'id': 187, 'text': '"Why are those soldiers stationed on the platform?" Sir Henry asked our driver.', 'translation': '"O askerler neden peronda nöbet tutuyor?" diye sordu Sir Henry sürücümüze.', 'notes': 'stationed: konuşlandırılmış.'}, {'id': 188, 'text': '"A convict has escaped from Princetown Prison, sir," answered the driver in a hushed tone.', 'translation': '"Princetown Hapishanesi\'nden bir mahkum firar etti efendim," dedi sürücü alçak sesle.', 'notes': 'escaped: firar etmiş.'}, {'id': 189, 'text': '"It is Selden, the notorious Notting Hill murderer, who butchered a whole family."', 'translation': '"Bütün bir aileyi vahşice katleden meşhur Notting Hill katili Selden bu firari."', 'notes': 'notorious murderer: adı çıkmış katil.'}, {'id': 190, 'text': '"He has been out on the wild moor for three days, and the warders are watching every road."', 'translation': '"Üç gündür o vahşi bataklıkta saklanıyor ve gardiyanlar her yolu gözetim altında tutuyor."', 'notes': 'has been out: dışarıda saklanmaktadır.'}, {'id': 191, 'text': '"He must be starving and desperate by now; any lonely house could be attacked."', 'translation': '"Şimdiye dek açlıktan kırılmış ve gözü dönmüş olmalı; ıssız her eve saldırabilir."', 'notes': 'must be starving: açlıktan ölüyor olmalı.'}, {'id': 192, 'text': 'Our carriage climbed higher and higher along the steep, winding road.', 'translation': 'Arabamız dik ve kıvrımlı yol boyunca gittikçe daha da yukarılara tırmandı.', 'notes': 'higher and higher: gittikçe daha yükseğe.'}, {'id': 193, 'text': 'Suddenly, the vast, desolate expanse of the moor opened before our eyes.', 'translation': 'Birdenbire, bataklığın engin ve ıssız uzantısı gözlerimizin önüne serildi.', 'notes': 'desolate expanse: ıssız genişlik.'}, {'id': 194, 'text': 'Huge granite tors rose like prehistoric sentinels against the gloomy evening sky.', 'translation': 'Devasa granit kayalıklar, kasvetli akşam göğüne karşı tarih öncesinden kalma nöbetçiler gibi yükseliyordu.', 'notes': 'prehistoric sentinels: tarih öncesi nöbetçiler.'}, {'id': 195, 'text': 'A cold, damp wind blew across the heather, carrying an indescribable feeling of loneliness.', 'translation': 'Fundalıkların üzerinden esen soğuk, nemli rüzgar tarif edilemez bir yalnızlık hissi taşıyordu.', 'notes': 'heather: süpürge otu, funda.'}, {'id': 196, 'text': '"It is a wild and forbidding place," Sir Henry murmured, pulling his coat tight around him.', 'translation': '"Burası vahşi ve ürkütücü bir yer," diye mırıldandı Sir Henry, paltosunu sıkıca kendine sararak.', 'notes': 'forbidding: tekinsiz, ürkütücü.'}, {'id': 197, 'text': '"Yet it is the home of my people, and I am proud to claim it."', 'translation': '"Yine de halkımın, ailemin yurdudur burası ve ona sahip çıkmaktan gurur duyuyorum."', 'notes': 'claim it: ona sahip çıkmak.'}, {'id': 198, 'text': 'In the distance, the towers of Baskerville Hall appeared among the darkening trees.', 'translation': "Uzaktaki kararan ağaçların arasında Baskerville Malikanesi'nin kuleleri belirdi.", 'notes': 'darkening trees: kararan ağaçlar.'}, {'id': 199, 'text': 'The ancient stone mansion looked dark and melancholy, like a fortress guarding ancient secrets.', 'translation': 'Eski taş konak, kadim sırları koruyan bir hisar gibi karanlık ve kederli görünüyordu.', 'notes': 'melancholy: hüzünlü, kederli.'}, {'id': 200, 'text': 'As we entered the iron gates, a heavy shadow fell across our path, silencing all conversation.', 'translation': 'Demir kapılardan içeri girerken yolumuzun üzerine ağır bir gölge düştü ve tüm sohbeti kesti.', 'notes': 'silencing: susturarak.'}]}, {'page_no': 11, 'title': 'Arrival at Baskerville Hall', 'tr_title': "Baskerville Malikanesi'ne Varış ve Barrymore Çifti", 'vocab_focus': [('mansion', 'büyük konak, malikane'), ('hearth', 'ocak, şömine başı'), ('portrait', 'portre, yağlıboya tablo'), ('butler', 'baş uşak'), ('sombre', 'kasvetli, hüzünlü'), ('ancestral', 'atalardan kalma'), ('resignation', 'istifa, ayrılma talebi'), ('legacy', 'miras, vasiyet')], 'sentences': [{'id': 201, 'text': 'The great hall of the mansion was dimly lit by a blazing log fire upon the ancient hearth.', 'translation': 'Konağın devasa salonu, antik şöminede yanan odun ateşinin loş ışığıyla aydınlanıyordu.', 'notes': 'dimly lit: loş ışıkla aydınlatılmış.'}, {'id': 202, 'text': 'A tall man with a full black beard stepped forward from the shadows to greet us.', 'translation': 'Bizi karşılamak üzere gölgelerin arasından gür siyah sakallı, uzun boylu bir adam öne çıktı.', 'notes': 'full black beard: gür kara sakal.'}, {'id': 203, 'text': '"Welcome to Baskerville Hall, Sir Henry," he said with a respectful bow.', 'translation': '"Baskerville Malikanesi\'ne hoş geldiniz Sir Henry," dedi saygıyla eğilerek.', 'notes': 'respectful bow: saygılı selam.'}, {'id': 204, 'text': 'It was Barrymore, the butler whose beard reminded me so vividly of the London cab spy.', 'translation': "Bu kişi, sakalı bana Londra'daki fayton casusunu çok canlı biçimde hatırlatan baş uşak Barrymore'du.", 'notes': 'reminded vividly: canlı şekilde hatırlattı.'}, {'id': 205, 'text': 'His pale wife, a heavy woman with a grim, emotionless mouth, stood silently beside him.', 'translation': 'Asık, duygusuz dudaklarıyla iri yarı, solgun karısı da sessizce yanında dikiliyordu.', 'notes': 'emotionless: hissiz, duygusuz.'}, {'id': 206, 'text': 'Sir Henry looked around the gloomy, wood-panelled room with mixed feelings.', 'translation': 'Sir Henry, ahşap kaplamalı o kasvetli odaya karışık duygularla bakındı.', 'notes': 'wood-panelled: ahşap panelli.'}, {'id': 207, 'text': '"It\'s easy to see why my poor uncle grew melancholy in such a dark place," he remarked.', 'translation': '"Zavallı amcamın böylesine karanlık bir yerde neden melankoliye kapıldığını anlamak hiç de zor değil," dedi.', 'notes': 'easy to see: anlaması kolay.'}, {'id': 208, 'text': '"We will soon install electric lights and make this old hall bright and cheerful."', 'translation': '"Yakında elektrik lambaları taktıracağız ve bu eski salonu aydınlık ve neşeli hale getireceğiz."', 'notes': 'bright and cheerful: aydınlık ve neşeli.'}, {'id': 209, 'text': 'High upon the walls hung dark oil portraits of past generations of the Baskerville line.', 'translation': 'Duvarların yüksek kısımlarında Baskerville soyunun geçmiş nesillerine ait koyu renk yağlıboya portreler asılıydı.', 'notes': 'oil portraits: yağlıboya tablolar.'}, {'id': 210, 'text': 'Knights in armour, Cavaliers with lace collars, and judges in powdered wigs stared down at us.', 'translation': 'Zırhlı şövalyeler, dantel yakalı süvariler ve pudralı peruklu yargıçlar tepeden bize bakıyordu.', 'notes': 'powdered wigs: pudralı peruklar.'}, {'id': 211, 'text': "After we finished a modest dinner, Barrymore lingered near Sir Henry's chair.", 'translation': "Mütevazı akşam yemeğimizi bitirdikten sonra Barrymore, Sir Henry'nin sandalyesinin yakınında oyalandı.", 'notes': 'lingered: oyalandı, bekledi.'}, {'id': 212, 'text': '"Sir Henry, my wife and I wish to give our notice to leave as soon as you find new servants,"', 'translation': '"Sir Henry, siz yeni hizmetkarlar bulur bulmaz eşim ve ben ayrılmak için müsaadenizi rica ediyoruz,"', 'notes': 'give notice: istifasını bildirmek.'}, {'id': 213, 'text': '"Leave? But your family has served Baskerville Hall for generations!" Sir Henry exclaimed.', 'translation': '"Ayrılmak mı? Fakat aileniz nesillerdir Baskerville Malikanesi\'ne hizmet ediyor!" diye haykırdı Sir Henry.', 'notes': 'for generations: nesiller boyunca.'}, {'id': 214, 'text': '"We were deeply attached to Sir Charles, sir, and his terrible death has made the Hall painful for us."', 'translation': '"Sir Charles\'a yürekten bağlıydık efendim ve onun korkunç ölümü burayı bizim için çok acı verici hale getirdi."', 'notes': 'deeply attached: derinden bağlı.'}, {'id': 215, 'text': '"We will never feel easy in our minds here again, and we wish to start a small business in town."', 'translation': '"Burada bir daha asla huzurlu hissedemeyeceğiz ve kasabada küçük bir dükkân açmak istiyoruz."', 'notes': 'easy in mind: içi rahat olmak.'}, {'id': 216, 'text': '"Besides, Sir Charles left us each five hundred pounds in his generous will."', 'translation': '"Üstelik Sir Charles o cömert vasiyetinde her birimize beş yüz sterlin miras bıraktı."', 'notes': 'generous will: cömert vasiyetname.'}, {'id': 217, 'text': '"A five-hundred-pound legacy for each servant!" I thought, remembering Holmes\'s words.', 'translation': '"Her bir hizmetkar için beş yüz sterlinlik miras!" diye düşündüm Holmes\'un sözlerini anımsayarak.', 'notes': 'remembering: hatırlayarak.'}, {'id': 218, 'text': 'Here was a clear financial motive for someone who wished Sir Charles dead.', 'translation': "Sir Charles'ın ölümünü arzulayan biri için apaçık bir maddi gerekçe duruyordu karşımda.", 'notes': 'financial motive: mali çıkar / gerekçe.'}, {'id': 219, 'text': 'Sir Henry accepted their decision with regret, and we retired to our bedrooms on the second floor.', 'translation': 'Sir Henry kararlarını üzüntüyle kabul etti ve ikinci kattaki yatak odalarımıza çekildik.', 'notes': 'with regret: üzüntüyle.'}, {'id': 220, 'text': 'The wind howled outside against the stone walls, making the ancient timbers groan and creak.', 'translation': 'Dışarıda taş duvarlara çarparak uğuldayan rüzgar, eski tahta kirişleri inleterek gıcırdatıyordu.', 'notes': 'howled: uğuldadı.'}]}, {'page_no': 12, 'title': 'A Cry in the Night and the Grim Moor', 'tr_title': 'Gecenin Ağlayışı ve Kasvetli Bataklık', 'vocab_focus': [('sobbing', 'hıçkırarak ağlama'), ('agony', 'büyük acı, ızdırap'), ('corridor', 'koridor'), ('denial', 'inkar, yalanlama'), ('red-eyed', 'gözleri kan çanağı gibi'), ('heather', 'funda, süpürge otu'), ('vast', 'engin, uçsuz bucaksız'), ('solitary', 'yalnız, tek başına')], 'sentences': [{'id': 221, 'text': 'I could not sleep; the gloomy atmosphere of the old house weighed heavily upon my spirit.', 'translation': 'Uyuyamıyordum; eski konağın o kasvetli havası ruhuma ağır bir yük gibi çöküyordu.', 'notes': 'weighed heavily: ağır basmak, çökmek.'}, {'id': 222, 'text': "Somewhere around two o'clock in the dead of night, a distinct sound broke the silence.", 'translation': 'Gecenin köründe, saat iki sularında belirgin bir ses sessizliği böldü.', 'notes': 'in the dead of night: gecenin zifiri karanlığında.'}, {'id': 223, 'text': 'It was the muffled sob of a woman, torn by uncontrollable grief and tears.', 'translation': 'Zapt edilemeyen bir keder ve gözyaşlarıyla parçalanmış bir kadının boğuk hıçkırığıydı bu.', 'notes': 'muffled sob: boğuk hıçkırık.'}, {'id': 224, 'text': 'The heartbreaking weeping continued for nearly ten minutes before fading into silence.', 'translation': 'Yürek parçalayan ağlayış, yerini sessizliğe bırakmadan önce yaklaşık on dakika boyunca sürdü.', 'notes': 'heartbreaking weeping: yürek parçalayan feryat.'}, {'id': 225, 'text': 'The next morning at breakfast, I asked Sir Henry if he had heard the nocturnal weeping.', 'translation': "Ertesi sabah kahvaltıda Sir Henry'ye geceki ağlayış sesini duyup duymadığını sordum.", 'notes': 'nocturnal weeping: gece ağlayışı.'}, {'id': 226, 'text': '"I heard it too, Watson; I thought at first it was only a nightmare," he replied.', 'translation': '"Ben de duydum Watson; ilk başta sadece bir kabus olduğunu sanmıştım," diye yanıtladı.', 'notes': 'nightmare: kabus.'}, {'id': 227, 'text': 'When Barrymore came in to clear the plates, I noticed his wife was not present.', 'translation': 'Barrymore tabakları toplamak için içeri girdiğinde karısının ortalıkta olmadığını fark ettim.', 'notes': 'clear the plates: tabakları kaldırmak.'}, {'id': 228, 'text': '"Barrymore, there are only two women in this house: your wife and the scullery maid."', 'translation': '"Barrymore, bu evde sadece iki kadın var: eşiniz ve bulaşıkçı kız."', 'notes': 'scullery maid: bulaşıkçı hizmetçi kız.'}, {'id': 229, 'text': '"Which of them was crying so bitterly in the night?" I asked directly.', 'translation': '"Geceleyin hangisi böylesine acı acı ağlıyordu?" diye doğrudan sordum.', 'notes': 'crying bitterly: acı acı ağlamak.'}, {'id': 230, 'text': 'Barrymore turned white, and his fingers trembled as he set down the silver tray.', 'translation': "Barrymore'un rengi bembeyaz oldu ve gümüş tepsiyi masaya bırakırken parmakları titredi.", 'notes': 'turned white: bembeyaz kesildi.'}, {'id': 231, 'text': '"It was not the maid, sir, and I assure you my wife was asleep all night," he lied.', 'translation': '"Hizmetçi değildi efendim ve temin ederim karım bütün gece uyuyordu," diye yalan söyledi.', 'notes': 'assure you: temin ederim ki.'}, {'id': 232, 'text': 'Yet when I encountered Mrs. Barrymore in the corridor an hour later, the truth was obvious.', 'translation': 'Fakat bir saat sonra koridorda Bayan Barrymore ile karşılaştığımda gerçek gün gibi ortadaydı.', 'notes': 'truth was obvious: gerçek aşikârdı.'}, {'id': 233, 'text': 'Her eyes were swollen and bloodshot, and she kept her gaze fixed upon the floor.', 'translation': 'Gözleri şişmiş ve kan çanağına dönmüştü; bakışlarını ısrarla yere dikiyordu.', 'notes': 'swollen and bloodshot: şişmiş ve kanlanmış.'}, {'id': 234, 'text': '"Why was Barrymore lying? What dreadful secret is this family hiding?" I wondered.', 'translation': '"Barrymore neden yalan söylüyordu? Bu aile ne tür korkunç bir sırrı saklıyor?" diye düşündüm.', 'notes': 'what dreadful secret: nasıl korkunç bir sır.'}, {'id': 235, 'text': 'After lunch, I decided to walk out upon the moor to explore the surrounding country.', 'translation': 'Öğle yemeğinden sonra, etraftaki araziyi keşfetmek için bataklığa doğru yürümeye karar verdim.', 'notes': 'explore the country: araziyi keşfetmek.'}, {'id': 236, 'text': 'The vast, rolling wasteland of grey granite and yellow gorse stretched to the horizon.', 'translation': 'Boz granitten ve sarı katırtırnaklarından oluşan engin, dalgalı çorak topraklar ufka kadar uzanıyordu.', 'notes': 'yellow gorse: sarı katırtırnağı bitkisi.'}, {'id': 237, 'text': 'The wind whistled through the heather, whispering ancient tales of doom and death.', 'translation': 'Fundalıkların arasından ıslık çalan rüzgar, kadim felaket ve ölüm hikayelerini fısıldıyordu.', 'notes': 'whistled through: arasından ıslık çalarak esti.'}, {'id': 238, 'text': 'Nowhere could a human dwelling be seen, save for a few lonely shepherd huts in ruins.', 'translation': 'Harabe halindeki birkaç ıssız çoban kulübesi haricinde hiçbir insan barınağı görünmüyordu.', 'notes': 'save for: ...den başka, haricinde.'}, {'id': 239, 'text': 'A sense of oppressive isolation settled upon my heart as I walked alone.', 'translation': 'Yapayalnız yürürken yüreğime boğucu bir tecrit ve yalnızlık hissi çöktü.', 'notes': 'oppressive isolation: boğucu yalnızlık.'}, {'id': 240, 'text': 'Then, from behind a granite tor, rapid footsteps came hurrying toward me.', 'translation': 'Derken, granit bir kayalığın arkasından hızlı ayak sesleri bana doğru aceleyle yaklaşmaya başladı.', 'notes': 'came hurrying: aceleyle geldi.'}]}, {'page_no': 13, 'title': 'Meeting Mr. Stapleton of Merripit House', 'tr_title': "Merripit House'dan Jack Stapleton ile Tanışma", 'vocab_focus': [('naturalist', 'doğa bilimci'), ('butterfly', 'kelebek'), ('net', 'file, ağ'), ('botanist', 'botanikçi'), ('enthusiastic', 'hevesli, coşkulu'), ('mire', 'balçık bataklık'), ('treacherous', 'tekinsiz, haince tuzaklı'), ('bog', 'bataklık, batak')], 'sentences': [{'id': 241, 'text': 'A small, slender man with a butterfly net and a tin specimen box stepped out into the path.', 'translation': 'Elinde bir kelebek filesi ve teneke numune kutusu olan narin, ufak tefek bir adam patikaya çıktı.', 'notes': 'butterfly net: kelebek yakalama filesi.'}, {'id': 242, 'text': 'He had fair hair, a clean-shaven face, and looked about thirty-five years of age.', 'translation': 'Sarı saçları, sinekkaydı traşlı bir yüzü vardı ve yaklaşık otuz beş yaşlarında görünüyordu.', 'notes': 'clean-shaven: sinekkaydı traşlı.'}, {'id': 243, 'text': '"Forgive my presumption, but you must be Dr. Watson from Baker Street!" he called out cheerfully.', 'translation': '"Cüretimi bağışlayın ama siz Baker Sokağı\'ndan Doktor Watson olmalısınız!" diye seslendi neşeyle.', 'notes': 'forgive my presumption: haddimi aşmamı bağışlayın.'}, {'id': 244, 'text': '"I am Jack Stapleton, a naturalist living at Merripit House just across the valley."', 'translation': '"Ben Jack Stapleton; vadinin hemen karşısındaki Merripit Evi\'nde yaşayan bir doğa bilimciyim."', 'notes': 'naturalist: doğa bilimci.'}, {'id': 245, 'text': '"Dr. Mortimer mentioned your arrival, and your military bearing makes you easy to recognize."', 'translation': '"Dr. Mortimer geleceğinizden bahsetmişti ve askeri duruşunuz sizi tanımayı çok kolaylaştırıyor."', 'notes': 'military bearing: askeri duruş/tavır.'}, {'id': 246, 'text': '"How is your great friend Mr. Sherlock Holmes? Will he also visit our lonely moor?"', 'translation': '"Kıymetli dostunuz Bay Sherlock Holmes nasıllar? O da ıssız bataklığımızı ziyaret edecek mi?"', 'notes': 'how is: nasıldır?'}, {'id': 247, 'text': '"He is detained in London on important business," I replied with careful caution.', 'translation': '"Önemli bir iş nedeniyle Londra\'da alıkonuldu," diye yanıtladım temkinli bir dikkatle.', 'notes': 'detained: meşgul/alıkonulmuş.'}, {'id': 248, 'text': '"A pity! We country folk would value the opinion of such a celebrated detective,"', 'translation': '"Yazık! Biz taşra halkı böylesine meşhur bir dedektifin fikirlerine çok değer verirdik,"', 'notes': 'celebrated detective: ünlü dedektif.'}, {'id': 249, 'text': '"Sir Charles\'s death was a dreadful shock, though everyone accepts it was just his heart."', 'translation': '"Herkes kalbinden gittiğini kabul etse de Sir Charles\'ın ölümü korkunç bir şok oldu,"', 'notes': 'dreadful shock: korkunç sarsıntı.'}, {'id': 250, 'text': '"Do you think there was anything more sinister behind it?" Stapleton asked, watching me intently.', 'translation': '"Sizce bunun arkasında daha meşum, kötü bir şey var mıydı?" diye sordu Stapleton, beni dikkatle izleyerek.', 'notes': 'sinister: tekinsiz, uğursuz.'}, {'id': 251, 'text': '"I am merely a friend of Sir Henry, visiting him for a pleasant holiday," I evaded.', 'translation': '"Ben yalnızca hoş bir tatil için Sir Henry\'yi ziyaret eden bir dostuyum," diyerek geçiştirdim.', 'notes': 'evaded: savuşturdu / konuyu saptırdı.'}, {'id': 252, 'text': '"Of course, of course!" Stapleton smiled, nodding with apparent understanding.', 'translation': '"Elbette, gayet tabii!" diye gülümsedi Stapleton, anlar gibi başını sallayarak.', 'notes': 'apparent understanding: görünüşte anlama.'}, {'id': 253, 'text': '"Look over there toward the north; do you see that bright green patch among the brown hills?"', 'translation': '"Şuraya, kuzeye doğru bakın; kahverengi tepelerin arasındaki o parlak yeşil alanı görüyor musunuz?"', 'notes': 'bright green patch: parlak yeşil leke/bölge.'}, {'id': 254, 'text': '"That is the Great Grimpen Mire, the most perilous quicksand in the entire British Isles."', 'translation': '"Orası Büyük Grimpen Bataklığı\'dır; tüm Britanya Adaları\'nın en ölümcül bataklığıdır."', 'notes': 'perilous quicksand: tehlikeli bataklık.'}, {'id': 255, 'text': '"A single false step off the hidden path means instant and horrific death!"', 'translation': '"Gizli patikanın dışına atılacak tek bir yanlış adım, anında ve dehşet verici bir ölüm demektir!"', 'notes': 'false step: yanlış adım.'}, {'id': 256, 'text': '"Only yesterday, I saw an unfortunate moor pony wander in and get swallowed alive."', 'translation': '"Daha dün, oraya giren talihsiz bir bataklık midillisinin diri diri yutulduğunu gördüm."', 'notes': 'swallowed alive: canlı canlı yutuldu.'}, {'id': 257, 'text': '"Yet I have explored it thoroughly and learned the secret path to its hidden islands."', 'translation': '"Yine de orayı baştan başa keşfettim ve gizli adalarına giden saklı yolu öğrendim."', 'notes': 'explored thoroughly: dip köşe keşfetti.'}, {'id': 258, 'text': '"Rare orchids and exotic moths flourish there, far from the reach of ordinary men."', 'translation': '"Nadir orkideler ve egzotik güveler sıradan insanların erişemeyeceği orada serpilip gelişiyor."', 'notes': 'flourish: serpilmek, gelişmek.'}, {'id': 259, 'text': 'As he spoke, a small cyclopides butterfly fluttered past over the treacherous bog.', 'translation': 'O konuşurken, tekinsiz bataklığın üzerinden küçük bir kelebek kanat çırparak geçti.', 'notes': 'fluttered past: pırpır ederek uçtu.'}, {'id': 260, 'text': 'Stapleton immediately dashed after it with astonishing agility, leaping from tuft to tuft over the deadly mud.', 'translation': 'Stapleton ölümcül çamurun üzerindeki ot kümelerinden zıplayıp şaşırtıcı bir çeviklikle derhal peşine düştü.', 'notes': 'dashing after: peşinden fırlamak.'}]}, {'page_no': 14, 'title': 'The Horrors of the Grimpen Mire', 'tr_title': 'Grimpen Bataklığının Dehşeti ve Can Çekişen Midilli', 'vocab_focus': [('morass', 'bataklık, balçık'), ('quicksand', 'kum bataklığı, oynak bataklık'), ('struggle', 'çırpınmak, mücadele etmek'), ('submerge', 'suya/çamura batmak'), ('howl', 'ulumak, uğuldamak'), ('uncanny', 'tekinsiz, esrarengiz'), ('tremor', 'titreme, ürperti'), ('bitter', 'acı, amansız')], 'sentences': [{'id': 261, 'text': 'Stapleton returned after a few minutes, panting lightly and carefully placing the butterfly in his box.', 'translation': 'Stapleton birkaç dakika sonra hafifçe soluk soluğa geri döndü ve kelebeği dikkatlice kutusuna yerleştirdi.', 'notes': 'panting lightly: hafifçe nefes nefese.'}, {'id': 262, 'text': '"It is a rare specimen of the marsh fritillary," he said, wiping his moist brow.', 'translation': '"Bataklık fritillerinin ender bulunan bir numunesidir bu," dedi nemli alnını silerek.', 'notes': 'marsh: bataklık.'}, {'id': 263, 'text': 'Suddenly, a long, low moan drifted across the desolate expanse of the Grimpen Mire.', 'translation': "Birdenbire, Grimpen Bataklığı'nın ıssız uzantısından uzun, alçak bir inilti süzülüp geldi.", 'notes': 'drifted across: boydan boya süzüldü.'}, {'id': 264, 'text': 'It began as a deep, mournful rumble and swelled into a wild, terrifying roar.', 'translation': 'Derin, kederli bir uğultu olarak başladı ve vahşi, dehşet verici bir kükremeye dönüştü.', 'notes': 'swelled into: ...e dönüştü / kabardı.'}, {'id': 265, 'text': 'The fearful sound echoed against the distant granite rocks and died away into the wind.', 'translation': 'Korkunç ses uzak granit kayalıklarda yankılandı ve rüzgârın içinde kaybolup gitti.', 'notes': 'died away: yavaşça sönüp yok oldu.'}, {'id': 266, 'text': '"Good heavens! What was that?" I cried, turning pale as a cold chill gripped my heart.', 'translation': '"Aman Tanrım! O neydi öyle?" diye bağırdım; yüreğimi soğuk bir ürperti sararken rengim solmuştu.', 'notes': 'good heavens: aman Tanrım.'}, {'id': 267, 'text': '"The peasants say it is the Hound of the Baskervilles calling for its prey," Stapleton said with a strange smile.', 'translation': '"Köylüler bunun, avını çağıran Baskerville Tazısı olduğunu söyler," dedi Stapleton tuhaf bir tebessümle.', 'notes': 'calling for its prey: avını çağıran.'}, {'id': 268, 'text': '"You are an educated man; you cannot believe such nonsense!" I protested firmly.', 'translation': '"Siz eğitimli bir adamsınız; böylesi saçmalıklara inanamazsınız!" diye kararlılıkla karşı çıktım.', 'notes': 'such nonsense: böylesi saçmalık.'}, {'id': 269, 'text': '"Bogs make very queer noises sometimes," he answered calmly, looking out over the green mire.', 'translation': '"Bataklıklar bazen çok acayip sesler çıkarır," diye sakince yanıtladı, yeşil balçığa doğru bakarak.', 'notes': 'queer noises: tuhaf sesler.'}, {'id': 270, 'text': '"It is the mud settling, or the water rising, or perhaps a bittern booming in the reeds."', 'translation': '"Çamurun çökmesi, suyun yükselmesi veya sazlıklardaki bir balıkçıl kuşunun ötüşü olabilir."', 'notes': 'reeds: sazlıklar.'}, {'id': 271, 'text': '"No, no! That was the living voice of a giant beast!" I insisted.', 'translation': '"Hayır, hayır! O canlı bir dev yaratığın sesiydi!" diye ısrar ettim.', 'notes': 'living voice: canlı sesi.'}, {'id': 272, 'text': 'At that very instant, fifty yards away in the green slime, another tragedy unfolded.', 'translation': 'Tam o anda, elli yarda ötedeki yeşil balçıkta başka bir trajedi gözler önüne serildi.', 'notes': 'unfolded: açığa çıktı, yaşandı.'}, {'id': 273, 'text': 'A small moor pony had strayed off the hidden track into the fatal quicksand.', 'translation': 'Küçük bir bataklık midillisi gizli patikadan sapıp ölümcül bataklığa dalmıştı.', 'notes': 'strayed off: yolundan sapmıştı.'}, {'id': 274, 'text': 'It struggled frantically, tossing its mane and thrashing its legs against the black morass.', 'translation': 'Yelesini savurup bacaklarını siyah balçığa karşı çırparak delicesine mücadele ediyordu.', 'notes': 'struggled frantically: çılgınca çırpındı.'}, {'id': 275, 'text': 'The more it struggled, the deeper the hungry mire sucked its trembling body down.', 'translation': 'Hayvan çırpındıkça, açgözlü bataklık onun titreyen bedenini daha da derinlere çekiyordu.', 'notes': 'the more ... the deeper: ne kadar çoksa o kadar derin.'}, {'id': 276, 'text': 'A piercing, agonized scream tore from the dying creature as its neck submerged beneath the slime.', 'translation': 'Boynu balçığın altına batarken, can çekişen hayvandan kulak tırmalayıcı, acı dolu bir çığlık koptu.', 'notes': 'piercing scream: tiz çığlık.'}, {'id': 277, 'text': 'In less than two minutes, only a few oily bubbles remained upon the bright green surface.', 'translation': 'İki dakikadan kısa bir sürede parlak yeşil yüzeyde sadece birkaç yağlı hava kabarcığı kaldı.', 'notes': 'oily bubbles: yağlı baloncuklar.'}, {'id': 278, 'text': '"Gone!" Stapleton whispered with cold indifference. "The mire has swallowed it entirely."', 'translation': '"Gitti!" diye fısıldadı Stapleton soğuk bir kayıtsızlıkla. "Bataklık onu tamamen yuttu."', 'notes': 'cold indifference: soğuk kayıtsızlık.'}, {'id': 279, 'text': '"It is a dreadful place, yet it has an irresistible fascination for me,"', 'translation': '"Korkunç bir yer, yine de benim için karşı konulmaz bir çekiciliği var,"', 'notes': 'irresistible fascination: karşı konulmaz büyü/çekim.'}, {'id': 280, 'text': '"Come, Dr. Watson, let us walk to Merripit House; my sister Beryl will be glad to meet you."', 'translation': '"Gelin Dr. Watson, Merripit Evi\'ne yürüyelim; kız kardeşim Beryl sizinle tanışmaktan mutluluk duyacaktır."', 'notes': 'will be glad to: memnuniyet duyacaktır.'}]}, {'page_no': 15, 'title': "Miss Beryl Stapleton's Urgent Warning", 'tr_title': "Beryl Stapleton'ın Acil ve Israrlı Uyarısı", 'vocab_focus': [('brunette', 'esmer kadın'), ('exotic', 'egzotik, yabancı'), ('urgent', 'acil, ivedi'), ('mistaken', 'yanılmış, hatalı'), ('fervent', 'coşkulu, hararetli'), ('implore', 'yalvarmak, istirham etmek'), ('betray', 'ele vermek, ihanet etmek'), ('puzzled', 'şaşırmış, kafası karışmış')], 'sentences': [{'id': 281, 'text': 'Merripit House was a desolate stone cottage standing alone in the bleak hollow of the hills.', 'translation': 'Merripit Evi, tepelerin kasvetli çukurunda yapayalnız duran ıssız bir taş kır eviydi.', 'notes': 'desolate cottage: ıssız kır evi.'}, {'id': 282, 'text': 'As we neared the porch, Stapleton hurried ahead to put away his butterfly specimens.', 'translation': 'Biz verandaya yaklaşırken Stapleton kelebek numunelerini içeri bırakmak için önden aceleyle gitti.', 'notes': 'hurried ahead: önden aceleyle gitti.'}, {'id': 283, 'text': 'A young woman stepped out from the side garden onto the gravel path.', 'translation': 'Yan bahçeden çakıllı patikaya doğru genç bir kadın çıktı.', 'notes': 'stepped out: dışarı adım attı.'}, {'id': 284, 'text': 'She was remarkably beautiful, with dark eyes, olive skin, and an elegant, exotic figure.', 'translation': 'Koyu renk gözleri, buğday teni ve zarif, egzotik endamıyla fevkalade güzel bir kadındı.', 'notes': 'remarkably beautiful: son derece güzel.'}, {'id': 285, 'text': 'There was not the slightest family resemblance between her and the fair-haired Stapleton.', 'translation': 'Onunla sarışın Stapleton arasında en ufak bir aile benzerliği dahi yoktu.', 'notes': 'not the slightest: en ufak bile yok.'}, {'id': 286, 'text': 'Before I could speak, she rushed up to me with intense anxiety in her dark eyes.', 'translation': 'Ben konuşamadan, koyu renk gözlerinde yoğun bir endişeyle aceleyle yanıma geldi.', 'notes': 'rushed up to: yanına koştu.'}, {'id': 287, 'text': '"Go back!" she whispered passionately. "Go straight back to London, this very night!"', 'translation': '"Geri dönün!" diye fısıldadı hararetle. "Hemen bu gece doğruca Londra\'ya geri dönün!"', 'notes': 'go straight back: doğruca geri dön.'}, {'id': 288, 'text': '"Why should I go back?" I asked, startled by her sudden and vehement warning.', 'translation': '"Neden geri döneyim?" diye sordum, onun ani ve şiddetli uyarısıyla irkilerek.', 'notes': 'startled by: ile irkilen.'}, {'id': 289, 'text': '"I cannot explain, but for God\'s sake do what I ask you! Never set foot upon this moor again!"', 'translation': '"Açıklayamam, ama Tanrı aşkına sizden istediğimi yapın! Bu bataklığa bir daha asla ayak basmayın!"', 'notes': "for God's sake: Tanrı aşkına."}, {'id': 290, 'text': '"Miss Stapleton, I am not Sir Henry Baskerville; I am only his friend, Dr. Watson,"', 'translation': '"Matmazel Stapleton, ben Sir Henry Baskerville değilim; yalnızca onun dostu Doktor Watson\'ım,"', 'notes': 'only his friend: sadece onun dostu.'}, {'id': 291, 'text': 'The lady started in utter dismay and her hand flew to her throat in confusion.', 'translation': 'Genç kadın büyük bir dehşetle irkildi ve şaşkınlık içinde eli boğazına gitti.', 'notes': 'flew to throat: eli boğazına gitti.'}, {'id': 292, 'text': '"You are Dr. Watson? Oh, what have I said? Please forget every word!"', 'translation': '"Siz Doktor Watson mısınız? Ah, ben neler söyledim? Lütfen her kelimemi unutun!"', 'notes': 'what have I said: neler söyledim ben.'}, {'id': 293, 'text': '"How can I forget when you spoke with such deadly earnestness?" I pressed gently.', 'translation': '"Böylesine ölümcül bir ciddiyetle konuşmuşken nasıl unutabilirim?" diye üsteledim kibarca.', 'notes': 'deadly earnestness: ölümcül ciddiyet.'}, {'id': 294, 'text': '"It was merely a foolish sister\'s whim; I was terrified by the legend of the hound," she stammered.', 'translation': '"Yalnızca aptalca bir kız kardeş kaprisiydi; tazı efsanesinden çok korkmuştum," diye kekeledi.', 'notes': 'whim: kapris, anlık heves.'}, {'id': 295, 'text': '"Do not breathe a single word of what I said to my brother Jack! He would be furious with me!"', 'translation': '"Söylediklerimden ağabeyim Jack\'e tek bir kelime dahi bahsetmeyin! Bana küplere biner!"', 'notes': 'breathe a word: tek kelime çıtlatmak.'}, {'id': 296, 'text': 'Stapleton re-emerged from the house at that moment, carrying a plate of biscuits.', 'translation': 'Tam o anda Stapleton elinde bir tabak bisküviyle evden tekrar dışarı çıktı.', 'notes': 're-emerged: yeniden belirdi.'}, {'id': 297, 'text': '"I see you have already introduced yourself to Beryl," he remarked with a keen glance between us.', 'translation': '"Görüyorum ki kendinizi Beryl\'e çoktan tanıtmışsınız," dedi ikimizin arasına keskin bir bakış fırlatarak.', 'notes': 'keen glance: keskin bakış.'}, {'id': 298, 'text': '"Yes, we have been admiring the wild view across the hills," Miss Stapleton replied smoothly.', 'translation': '"Evet, tepelerin karşısındaki vahşi manzaraya hayranlıkla bakıyorduk," diye ustaca yanıtladı Matmazel Stapleton.', 'notes': 'smoothly: ustaca, pürüzsüzce.'}, {'id': 299, 'text': 'Her composure was astonishing, yet I could see the underlying dread in her dark eyes.', 'translation': 'Soğukkanlılığı hayranlık uyandırıcıydı, fakat kara gözlerinin altındaki o dehşeti görebiliyordum.', 'notes': 'underlying dread: alttaki dehşet.'}, {'id': 300, 'text': 'Why had she mistaken me for Sir Henry, and what peril was she trying so desperately to warn him against?', 'translation': 'Beni neden Sir Henry sanmıştı ve onu böylesine çaresizce hangi büyük tehlikeye karşı uyarmaya çalışıyordu?', 'notes': 'mistaken for: sanmak, karıştırmak.'}]}, {'page_no': 16, 'title': "Sir Henry's Growing Affection and Stapleton's Fury", 'tr_title': "Sir Henry'nin Beryl'e İlgisi ve Stapleton'ın Öfke Patlaması", 'vocab_focus': [('affection', 'sevgi, muhabbet'), ('fury', 'öfke patlaması, hiddet'), ('jealous', 'kıskanç'), ('intervene', 'araya girmek, müdahale etmek'), ('apology', 'özür'), ('attachment', 'bağlılık, gönül bağı'), ('temper', 'öfke, asabiyet'), ('mysterious', 'gizemli, esrarengiz')], 'sentences': [{'id': 301, 'text': 'During the following two weeks, Sir Henry visited Merripit House almost every day.', 'translation': "Takip eden iki hafta boyunca Sir Henry neredeyse her gün Merripit Evi'ni ziyaret etti.", 'notes': 'almost every day: hemen her gün.'}, {'id': 302, 'text': 'He was completely captivated by the dark beauty and gentle manners of Beryl Stapleton.', 'translation': "Beryl Stapleton'ın esmer güzelliği ve nazik tavırları karşısında adeta büyülenmişti.", 'notes': 'captivated by: ...e kapılmış, büyülenmiş.'}, {'id': 303, 'text': 'The young baronet spoke openly to me of his growing love and his desire to make her his wife.', 'translation': 'Genç baronet, ona karşı büyüyen aşkından ve onu karısı yapma arzusundan bana açıkça bahsetti.', 'notes': 'growing love: büyüyen aşk.'}, {'id': 304, 'text': 'Yet Jack Stapleton seemed deeply displeased whenever the two young people were together.', 'translation': 'Oysa Jack Stapleton, bu iki genç insan ne zaman yan yana gelse derin bir hoşnutsuzluk gösteriyordu.', 'notes': 'deeply displeased: derin hoşnutsuz.'}, {'id': 305, 'text': 'One morning, Sir Henry slipped away across the moor to meet Miss Stapleton alone.', 'translation': 'Bir sabah Sir Henry, Matmazel Stapleton ile baş başa buluşmak için gizlice bataklığa gitti.', 'notes': 'slipped away: sessizce sıvıştı.'}, {'id': 306, 'text': "Remembering Holmes's strict command never to leave him, I followed at a safe distance.", 'translation': "Holmes'un onu asla yalnız bırakmama yönündeki kesin emrini hatırlayarak güvenli bir mesafeden takip ettim.", 'notes': 'strict command: kesin emir.'}, {'id': 307, 'text': 'From the crest of a granite tor, I observed them talking earnestly upon the moor path.', 'translation': 'Granit bir kayalığın tepesinden, bataklık yolunda hararetle konuştuklarını gözlemledim.', 'notes': 'crest: zirve, tepe noktası.'}, {'id': 308, 'text': 'Sir Henry held her hands, but she seemed to be pleading with him to leave her.', 'translation': 'Sir Henry kadının ellerini tutuyordu, fakat kadın onu bırakıp gitmesi için yalvarıyor gibiydi.', 'notes': 'pleading with: ...e yalvarmak.'}, {'id': 309, 'text': 'Suddenly, Jack Stapleton appeared running over the heather with wild gestures.', 'translation': 'Aniden Jack Stapleton vahşi el kol hareketleriyle fundalıkların üzerinden koşarak ortaya çıktı.', 'notes': 'wild gestures: çılgınca hareketler.'}, {'id': 310, 'text': 'He rushed between them, his face pale and twisted with uncontrollable fury.', 'translation': 'Yüzü bembeyaz ve zapt edilemez bir öfkeyle çarpılmış halde ikisinin arasına daldı.', 'notes': 'uncontrollable fury: kontrolsüz öfke.'}, {'id': 311, 'text': 'He shouted violently at Sir Henry and ordered his sister to return home immediately.', 'translation': "Sir Henry'ye şiddetle bağırdı ve kız kardeşine derhal eve dönmesini emretti.", 'notes': 'ordered to: emretti.'}, {'id': 312, 'text': 'Sir Henry stood his ground, demanding an explanation for such outrageous insolence.', 'translation': 'Sir Henry geri adım atmadı ve böylesi hadsiz bir küstahlığa dair bir açıklama talep etti.', 'notes': 'stood his ground: geri adım atmadı / dik durdu.'}, {'id': 313, 'text': 'Miss Stapleton led her brother away, leaving Sir Henry standing bewildered upon the path.', 'translation': 'Matmazel Stapleton kardeşini oradan uzaklaştırdı; Sir Henry patikada şaşkınlık içinde kalakaldı.', 'notes': 'bewildered: şaşkın, afallamış.'}, {'id': 314, 'text': 'I walked down to meet him, and he recounted the extraordinary encounter with bitter indignation.', 'translation': 'Onunla buluşmak için aşağı indim ve bu olağanüstü karşılaşmayı bana acı bir öfkeyle anlattı.', 'notes': 'bitter indignation: kırgın bir infial/öfke.'}, {'id': 315, 'text': '"The fellow behaves like a raving madman!" Sir Henry exclaimed angrily.', 'translation': '"Herif zırdeli bir deli gibi davranıyor!" diye öfkeyle haykırdı Sir Henry.', 'notes': 'raving madman: zırdeli.'}, {'id': 316, 'text': '"He treats his sister as though she were his private property, forbidden to speak to anyone."', 'translation': '"Kız kardeşine adeta kendi özel mülküymüş ve kimseyle konuşması yasakmış gibi davranıyor."', 'notes': 'as though she were: sanki öyleymiş gibi.'}, {'id': 317, 'text': 'That very afternoon, Stapleton came in person to Baskerville Hall to offer an apology.', 'translation': "O gün öğleden sonra Stapleton, özür dilemek üzere Baskerville Malikanesi'ne bizzat geldi.", 'notes': 'in person: bizzat kendisi.'}, {'id': 318, 'text': '"I was foolishly overprotective," he explained with a contrite smile.', 'translation': '"Aptalca bir aşırı korumacılık sergiledim," diye açıkladı pişman bir tebessümle.', 'notes': 'contrite: pişman, mahcup.'}, {'id': 319, 'text': '"She is all I have in the world, and the thought of losing her made me lose my temper."', 'translation': '"Dünyada sahip olduğum tek varlık o ve onu kaybetme düşüncesi tepemi attırdı."', 'notes': 'lose my temper: tepem attı / öfkeme yenildim.'}, {'id': 320, 'text': "Sir Henry generously forgave him, but I remained deeply suspicious of the naturalist's real motives.", 'translation': 'Sir Henry onu cömertçe affetti, fakat ben doğa bilimcinin gerçek niyetleri konusunda derin şüpheler taşımayı sürdürdüm.', 'notes': 'remained suspicious: şüphe duymaya devam etti.'}]}, {'page_no': 17, 'title': "Barrymore's Midnight Secret at the Window", 'tr_title': "Barrymore'un Gece Yarısı Pencereden Mumla Sinyal Vermesi", 'vocab_focus': [('creak', 'gıcırdamak'), ('candle', 'mum'), ('signal', 'sinyal, işaret'), ('peer', 'dikkatle bakmak, gözetlemek'), ('confession', 'itiraf'), ('brother-in-law', 'kayınbirader'), ('starvation', 'açlık, açlıktan ölme'), ('sympathy', 'merhamet, anlayış')], 'sentences': [{'id': 321, 'text': 'A few nights later, around two in the morning, I heard cautious footsteps in the corridor outside my room.', 'translation': 'Birkaç gece sonra, sabah saat iki sularında odamın dışındaki koridorda temkinli ayak sesleri duydum.', 'notes': 'cautious footsteps: tedbirli ayak sesleri.'}, {'id': 322, 'text': 'I slipped out of bed, grabbed my revolver, and quietly peered into the darkness.', 'translation': 'Yataktan sessizce sıyrıldım, tabancamı kaptım ve karanlığa doğru usulca baktım.', 'notes': 'slipped out of bed: yataktan sessizce çıktı.'}, {'id': 323, 'text': 'Barrymore was creeping down the long hall, holding a lighted candle in his hand.', 'translation': 'Barrymore elinde yanan bir mum tutarak uzun koridorda sessizce süzülüyordu.', 'notes': 'creeping down: sessizce süzülmek.'}, {'id': 324, 'text': 'I woke Sir Henry, and together we followed the butler on bare feet without making a sound.', 'translation': "Sir Henry'yi uyandırdım ve çıplak ayakla tek bir ses bile çıkarmadan uşağı birlikte takip ettik.", 'notes': 'bare feet: çıplak ayaklar.'}, {'id': 325, 'text': 'Barrymore entered an empty, unfurnished room at the end of the western wing.', 'translation': 'Barrymore batı kanadının sonundaki boş, eşyasız bir odaya girdi.', 'notes': 'unfurnished: döşenmemiş, eşyasız.'}, {'id': 326, 'text': 'He went to the window that commanded the blackest and wildest part of the moor.', 'translation': 'Bataklığın en karanlık ve en vahşi kısmına tepeden bakan pencereye gitti.', 'notes': 'commanded: manzaraya hakimdi.'}, {'id': 327, 'text': 'He held the candle close to the glass and peered intently into the pitch-black night.', 'translation': 'Mumu cama yaklaştırdı ve zifiri karanlık geceye doğru dikkatle baktı.', 'notes': 'pitch-black night: zifiri karanlık gece.'}, {'id': 328, 'text': 'For several minutes he stood motionless, waiting for an answering sign from the wilderness.', 'translation': 'Bozkırdan bir karşılık işareti bekleyerek birkaç dakika boyunca kıpırdamadan durdu.', 'notes': 'motionless: hareketsiz.'}, {'id': 329, 'text': 'Suddenly, a tiny point of yellow light blinked far out upon the black rocks of the moor.', 'translation': 'Birdenbire, bataklığın kara kayalıkları üzerinde çok uzakta minik sarı bir ışık noktası yanıp söndü.', 'notes': 'blinked: yanıp söndü.'}, {'id': 330, 'text': 'Barrymore gave a low sigh of satisfaction and waved his candle once before extinguishing the flame.', 'translation': 'Barrymore tatmin olmuş alçak bir iç çekti ve alevi söndürmeden önce mumunu bir kez salladı.', 'notes': 'extinguishing: söndürerek.'}, {'id': 331, 'text': '"What are you doing here, Barrymore?" Sir Henry suddenly demanded, bursting into the room.', 'translation': '"Burada ne yapıyorsun Barrymore?" diye odaya dalarak sertçe çıkıştı Sir Henry.', 'notes': 'bursting into: odaya dalarak.'}, {'id': 332, 'text': 'The butler gasped in terror, dropping the candle, and backed against the wall with trembling limbs.', 'translation': 'Uşak dehşet içinde soluğu kesilip mumu düşürdü ve titreyen bacaklarıyla duvara yaslandı.', 'notes': 'gasped in terror: dehşetle soluğu kesildi.'}, {'id': 333, 'text': '"Nothing, sir! I was only making sure the window was securely fastened!" he stammered.', 'translation': '"Hiçbir şey efendim! Sadece pencerenin sıkıca kilitli olduğundan emin oluyordum!" diye kekeledi.', 'notes': 'securely fastened: sıkıca kilitlenmiş.'}, {'id': 334, 'text': '"Do not lie to me! We saw you signaling to someone out upon the moor!"', 'translation': '"Bana yalan söyleme! Bataklıktaki birine sinyal verdiğini kendi gözlerimizle gördük!"', 'notes': 'signaling: işaret vermek.'}, {'id': 335, 'text': 'At that moment, the door opened and Mrs. Barrymore ran into the room, sobbing bitterly.', 'translation': 'O anda kapı açıldı ve Bayan Barrymore acı acı hıçkırarak odaya koştu.', 'notes': 'sobbing bitterly: acı acı ağlayarak.'}, {'id': 336, 'text': '"Do not blame him, Sir Henry! It is my fault, all mine!" she cried, throwing herself at his feet.', 'translation': '"Onu suçlamayın Sir Henry! Suç bende, hepsi benim suçum!" diye haykırdı ayaklarına kapanarak.', 'notes': 'throwing at feet: ayaklarına kapanmak.'}, {'id': 337, 'text': '"The man out on the moor is Selden, the escaped convict; he is my younger brother!"', 'translation': '"Bataklıktaki adam firari mahkum Selden\'dır; o benim küçük erkek kardeşim!"', 'notes': 'escaped convict: firari mahkum.'}, {'id': 338, 'text': '"He was starving among the rocks, and we could not let him die of cold and hunger!"', 'translation': '"Kayalıklar arasında açlıktan ölüyordu ve onun soğuktan ile açlıktan ölmesine seyirci kalamazdık!"', 'notes': 'starving: açlıktan ölmek.'}, {'id': 339, 'text': '"The candle was our signal that food was ready for him to collect at the rocks."', 'translation': '"Mum, yiyeceğin kayalıklardan alması için hazır olduğuna dair işaretimizdi."', 'notes': 'ready for him to collect: alması için hazır.'}, {'id': 340, 'text': 'The mystery of the nocturnal weeping was solved, but the convict was still loose upon the moor.', 'translation': 'Geceki ağlayışın gizemi çözülmüştü, fakat katil mahkum hâlâ bataklıkta serbestçe dolaşıyordu.', 'notes': 'loose: serbest, başıboş.'}]}, {'page_no': 18, 'title': 'The Pursuit of Selden Across the Moor', 'tr_title': "Bataklıkta Selden'ın Peşine Düşüş ve Kayalıktaki Siluet", 'vocab_focus': [('pursuit', 'takip, kovalama'), ('silhouette', 'siluet, gölge profil'), ('fugitive', 'kaçak, firari'), ('curse', 'lanet savurmak'), ('boulder', 'iri kaya parçası'), ('tor', 'sivri kayalık tepe'), ('solitary', 'tek başına, yalnız'), ('shadowy', 'gölgeli, esrarengiz')], 'sentences': [{'id': 341, 'text': '"This brutal murderer cannot be allowed to roam freely!" Sir Henry declared indignantly.', 'translation': '"Bu acımasız katilin serbestçe dolaşmasına izin verilemez!" diye belirtti Sir Henry hiddetle.', 'notes': 'roam freely: başıboş dolaşmak.'}, {'id': 342, 'text': '"Watson, grab your revolver! We must capture this villain before he murders someone else!"', 'translation': '"Watson, tabancanı kap! Başka birini öldürmeden önce bu alçağı yakalamalıyız!"', 'notes': 'capture: yakalamak, ele geçirmek.'}, {'id': 343, 'text': 'We ran out into the chilling night air and hurried toward the distant candle light.', 'translation': 'Dondurucu gece havasına çıktık ve uzaktaki mum ışığına doğru hızla koştuk.', 'notes': 'chilling night air: dondurucu gece havası.'}, {'id': 344, 'text': 'The wind howled fiercely across the wasteland, driving cold drops of rain into our faces.', 'translation': 'Rüzgar çorak arazide şiddetle uğulduyor, yüzümüze soğuk yağmur damlaları savuruyordu.', 'notes': 'howled fiercely: şiddetle uğuldadı.'}, {'id': 345, 'text': 'Suddenly, by the faint yellow glow of a candle, we saw a horrific figure crouching among the rocks.', 'translation': 'Birdenbire, bir mumun silik sarı ışığında, kayalar arasına çömelmiş korkunç bir siluet gördük.', 'notes': 'crouching: çömelmiş.'}, {'id': 346, 'text': 'It was a wild, gaunt creature with matted hair and a bestial face covered in grime.', 'translation': 'Keçeleşmiş saçları ve kire bulanmış vahşi çehresiyle yabani, bir deri bir kemik kalmış bir yaratıktı.', 'notes': 'bestial face: hayvani yüz.'}, {'id': 347, 'text': 'The convict looked up, saw us charging toward him, and uttered a blood-curdling curse.', 'translation': 'Mahkum kafasını kaldırdı, üzerine doğru koştuğumuzu gördü ve kan donduran bir lanet savurdu.', 'notes': 'blood-curdling: kan dondurucu.'}, {'id': 348, 'text': 'He hurled a heavy stone at us and leaped away into the darkness like a mountain goat.', 'translation': 'Bize doğru ağır bir taş fırlattı ve bir dağ keçisi gibi karanlığın içine sıçradı.', 'notes': 'hurled: fırlattı.'}, {'id': 349, 'text': '"Halt! In the name of the law!" I shouted, firing my revolver into the air to intimidate him.', 'translation': '"Dur! Kanun namına!" diye bağırdım, onu korkutmak için tabancamı havaya ateşleyerek.', 'notes': 'in the name of the law: kanun namına.'}, {'id': 350, 'text': 'The flash lit up the rocks for a split second, but Selden was extraordinarily swift and nimble.', 'translation': 'Namludan çıkan alev kayalıkları saniyenin bir kesri aydınlattı, ama Selden fevkalade hızlı ve çevikti.', 'notes': 'split second: saniyenin kesri.'}, {'id': 351, 'text': 'He vanished among the granite clefts, knowing every boulder and hiding place of the moor.', 'translation': 'Bataklığın her kayasını ve saklanma yerini bildiğinden granit yarıkların arasında gözden kayboldu.', 'notes': 'clefts: yarıklar.'}, {'id': 352, 'text': 'Out of breath, Sir Henry and I halted our pursuit near the crest of a high ridge.', 'translation': 'Nefes nefese kalan Sir Henry ve ben yüksek bir sırtın tepesine yakın takibi bıraktık.', 'notes': 'halted pursuit: takibi durdurdu.'}, {'id': 353, 'text': 'At that very moment, the clouds parted above, and a bright moon illuminated the landscape.', 'translation': 'Tam o anda yukarıdaki bulutlar aralandı ve parlak bir dolunay araziyi aydınlattı.', 'notes': 'clouds parted: bulutlar yarıldı/aralandı.'}, {'id': 354, 'text': 'High upon the pinnacle of a black tor stood the solitary figure of a tall, thin man.', 'translation': 'Kara bir kayalığın doruk noktasında uzun boylu, ince bir adamın tek başına duran silueti yükseliyordu.', 'notes': 'pinnacle: doruk, zirve.'}, {'id': 355, 'text': 'He stood with his arms folded across his chest, staring intently down across the moor.', 'translation': 'Kollarını göğsünde kavuşturmuş vaziyette duruyor ve pürdikkat bataklığa doğru aşağı bakıyordu.', 'notes': 'arms folded: kolları kavuşturulmuş.'}, {'id': 356, 'text': 'He was definitely not Selden, nor was he any country labourer or local peasant.', 'translation': 'O kesinlikle Selden değildi; ne bir tarım işçisi ne de yerel bir köylüydü.', 'notes': 'nor was he: ne de oydu.'}, {'id': 357, 'text': '"Look, Sir Henry! Over there on the rock!" I whispered, pointing my arm.', 'translation': '"Bakın Sir Henry! Orada, kayanın üzerinde!" diye fısıldadım kolumu uzatarak.', 'notes': 'pointing: işaret ederek.'}, {'id': 358, 'text': 'Sir Henry turned his head, but in that single second a cloud drifted over the moon.', 'translation': 'Sir Henry başını çevirdi, fakat tam o saniyede bir bulut ayın önünü kapattı.', 'notes': 'drifted over: önüne geçti.'}, {'id': 359, 'text': 'When the silvery light returned, the pinnacle was utterly empty.', 'translation': 'Gümüşi ışık geri döndüğünde, kayalığın zirvesi tamamen boştu.', 'notes': 'utterly empty: tamamen boş.'}, {'id': 360, 'text': 'Who was this shadowy watcher living out among the ancient prehistoric stones?', 'translation': 'Tarih öncesi kadim taşlar arasında yaşayan bu esrarengiz gözcü de kimdi?', 'notes': 'shadowy watcher: gölgeli gözlemci.'}]}, {'page_no': 19, 'title': 'The Secret of Laura Lyons', 'tr_title': "Laura Lyons'ın Sırrı ve Yakılan Mektup", 'vocab_focus': [('fragments', 'parçalar, kırıntılar'), ('appointment', 'randevu, buluşma'), ('initials', 'ismin baş harfleri'), ('distress', 'sıkıntı, darlık'), ('divorce', 'boşanma'), ('remorse', 'vicdan azabı, pişmanlık'), ('postscript', 'dipnot, mektup sonu notu (P.S.)'), ('confide', 'sırrını açmak, güvenip anlatmak')], 'sentences': [{'id': 361, 'text': 'The next morning, Barrymore approached me in private with a grateful and humble expression.', 'translation': 'Ertesi sabah Barrymore, minnettar ve mahcup bir ifadeyle gizlice yanıma geldi.', 'notes': 'approached in private: gizlice yanaştı.'}, {'id': 362, 'text': '"Dr. Watson, you were merciful to my wife last night, and I wish to repay your kindness."', 'translation': '"Doktor Watson, dün gece karıma çok merhametli davrandınız ve bu iyiliğinizin karşılığını ödemek isterim."', 'notes': 'merciful: merhametli.'}, {'id': 363, 'text': '"There is a secret about Sir Charles\'s death that I never revealed to the coroner."', 'translation': '"Sir Charles\'ın ölümü hakkında adli tabibe asla açıklamadığım bir sır var."', 'notes': 'never revealed: asla açıklamadı.'}, {'id': 364, 'text': '"On the morning of the day he died, Sir Charles received a letter with a Coombe Tracey postmark."', 'translation': '"Öldüğü günün sabahında Sir Charles, üzerinde Coombe Tracey posta damgası olan bir mektup aldı."', 'notes': 'postmark: posta damgası.'}, {'id': 365, 'text': '"My wife found the charred fragments of that letter in the fireplace the next morning."', 'translation': '"Karım ertesi sabah o mektubun kömürleşmiş parçalarını şöminenin içinde buldu."', 'notes': 'charred fragments: kömürleşmiş parçalar.'}, {'id': 366, 'text': '"Only the postscript at the bottom was legible; it was in a woman\'s delicate handwriting."', 'translation': '"Yalnızca en alttaki dipnot okunabiliyordu; zarif bir kadın el yazısıyla yazılmıştı."', 'notes': 'delicate handwriting: zarif el yazısı.'}, {'id': 367, 'text': '"It read: \'Please, please burn this letter, and be at the gate by ten o\'clock. L.L.\'"', 'translation': '"Şöyle yazıyordu: \'Lütfen, yalvarırım bu mektubu yakın ve saat onda kapıda olun. L.L.\'"', 'notes': 'burn this letter: bu mektubu yak.'}, {'id': 368, 'text': '"L.L.! Those initials must belong to Laura Lyons of Coombe Tracey!" I realized immediately.', 'translation': '"L.L.! Bu baş harfler Coombe Tracey\'deki Laura Lyons\'a ait olmalı!" diye hemen idrak ettim.', 'notes': 'initials: baş harfler.'}, {'id': 369, 'text': 'She was the daughter of old Frankland, an eccentric old gentleman living nearby.', 'translation': 'Civarda yaşayan Frankland adındaki tuhaf, eksantrik yaşlı bir beyefendinin kızıydı bu hanım.', 'notes': 'eccentric: eksantrik, garip huylu.'}, {'id': 370, 'text': 'Without losing a moment, I hired a dog-cart and drove directly to Coombe Tracey.', 'translation': "Bir an bile kaybetmeden iki tekerlekli bir araba kiraladım ve doğruca Coombe Tracey'ye sürdüm.", 'notes': 'without losing a moment: bir an kaybetmeden.'}, {'id': 371, 'text': 'Mrs. Laura Lyons was an extremely handsome woman, though her face showed signs of sorrow and hardship.', 'translation': 'Bayan Laura Lyons fevkalade güzel bir kadındı, gerçi yüzü keder ve zorlukların izlerini taşıyordu.', 'notes': 'signs of sorrow: keder izleri.'}, {'id': 372, 'text': '"Did you write a letter to Sir Charles Baskerville asking him to meet you at the wicket-gate?" I asked.', 'translation': '"Sir Charles Baskerville\'e bahçe kapısında buluşmayı rica eden bir mektup yazdınız mı?" diye sordum.', 'notes': 'asking him to meet: buluşmasını rica eden.'}, {'id': 373, 'text': 'She turned pale and clenched her trembling hands together upon her lap.', 'translation': 'Kadının rengi soldu ve kucağında titreyen ellerini sımsıkı kenetledi.', 'notes': 'clenched hands: ellerini kenetledi.'}, {'id': 374, 'text': '"Yes, I did," she confessed in a strained voice. "I was in desperate financial distress."', 'translation': '"Evet, yazdım," diye gergin bir sesle itiraf etti. "Çaresiz bir maddi sıkıntı içerisindeydim."', 'notes': 'strained voice: gergin/zoraki ses.'}, {'id': 375, 'text': '"My husband deserted me years ago, and I needed money to secure an official divorce."', 'translation': '"Kocam yıllar önce beni terk etti ve resmi bir boşanma sağlayabilmek için paraya ihtiyacım vardı."', 'notes': 'deserted: terk etti.'}, {'id': 376, 'text': '"Sir Charles was known for his limitless charity, and someone advised me to appeal to him."', 'translation': '"Sir Charles sınırsız hayırseverliğiyle tanınırdı ve biri bana ona başvurmamı tavsiye etti."', 'notes': 'limitless charity: sınırsız hayırseverlik.'}, {'id': 377, 'text': '"Who advised you? Was it Mr. Stapleton of Merripit House?" I pressed sharply.', 'translation': '"Bunu size kim tavsiye etti? Merripit Evi\'nden Bay Stapleton mı?" diye sertçe üsteledim.', 'notes': 'pressed sharply: sertçe üsteledi.'}, {'id': 378, 'text': 'She blushed deeply and avoided looking into my eyes.', 'translation': 'Yanakları kıpkırmızı oldu ve gözlerimin içine bakmaktan kaçındı.', 'notes': 'blushed deeply: derin kızardı.'}, {'id': 379, 'text': '"Did you keep the appointment at the gate?" I asked.', 'translation': '"Peki kapıdaki randevuya gittiniz mi?" diye sordum.', 'notes': 'keep the appointment: randevuya gitmek.'}, {'id': 380, 'text': '"No! I swear to God I never went! Someone provided the help from another source!"', 'translation': '"Hayır! Tanrı\'ya yemin ederim ki gitmedim! Biri bana başka bir kaynaktan yardım sağladı!"', 'notes': "swear to God: Tanrı'ya yemin ederim."}]}, {'page_no': 20, 'title': 'Holmes in the Stone Hut', 'tr_title': 'Tarihi Taş Kulübedeki Gizemli Adam: Sherlock Holmes!', 'vocab_focus': [('hut', 'kulübe, taş barınak'), ('prehistoric', 'tarih öncesi'), ('revolver', 'altıpatlar tabanca'), ('intruder', 'davetsiz misafir, izinsiz giren'), ('panier', 'sepet'), ('blanket', 'battaniye'), ('delight', 'büyük sevinç, haz'), ('reunion', 'yeniden kavuşma, buluşma')], 'sentences': [{'id': 381, 'text': 'Learning that the mysterious watcher lived in an ancient stone hut upon Black Tor, I set out immediately.', 'translation': "Esrarengiz gözcünün Black Tor'daki eski bir taş kulübede yaşadığını öğrenince hemen yola koyuldum.", 'notes': 'set out immediately: derhal yola koyuldu.'}, {'id': 382, 'text': 'The prehistoric huts were circular stone dwellings built by ancient Britons thousands of years ago.', 'translation': 'Tarih öncesi kulübeler, binlerce yıl önce kadim Britonlar tarafından inşa edilmiş dairesel taş barınaklardı.', 'notes': 'circular stone dwellings: dairesel taş konutlar.'}, {'id': 383, 'text': 'I climbed the rocky slope cautiously, gripping my revolver ready in my right hand.', 'translation': 'Sağ elimde ateş etmeye hazır tabancamı kavrayarak kayalık yamacı temkinle tırmandım.', 'notes': 'rocky slope: kayalık yamaç.'}, {'id': 384, 'text': 'Reaching the doorway of the chosen hut, I saw signs of recent human habitation inside.', 'translation': 'Seçilen kulübenin kapı boşluğuna vardığımda içeride yakın zamana ait insan yaşamı izleri gördüm.', 'notes': 'human habitation: insan yerleşimi.'}, {'id': 385, 'text': 'A bundle of dry heather served as a bed, covered by a waterproof military blanket.', 'translation': 'Su geçirmez askeri bir battaniyeyle örtülmüş kuru funda demeti yatak vazifesi görüyordu.', 'notes': 'waterproof: su geçirmez.'}, {'id': 386, 'text': 'In the corner stood several empty tins of tinned tongue and a loaf of bread.', 'translation': 'Köşede birkaç boş konserve sığır dili kutusu ve bir somun ekmek duruyordu.', 'notes': 'tinned tongue: konserve dil.'}, {'id': 387, 'text': 'On a flat granite slab lay a sheet of paper with writing in pencil.', 'translation': 'Düz bir granit taşın üzerinde kurşun kalemle yazılmış bir kağıt parçası yatıyordu.', 'notes': 'granite slab: granit taş levha.'}, {'id': 388, 'text': "I picked it up and read: 'Dr. Watson has gone to Coombe Tracey.'", 'translation': "Kağıdı elime aldım ve okudum: 'Doktor Watson Coombe Tracey'ye gitti.'", 'notes': 'has gone: gitti.'}, {'id': 389, 'text': 'My heart bounded; this mysterious stranger was tracking my every movement!', 'translation': 'Yüreğim ağzıma geldi; bu gizemli yabancı benim her hareketimi adım adım izliyordu!', 'notes': 'heart bounded: yüreği hopladı.'}, {'id': 390, 'text': 'Suddenly, a shadow fell across the threshold, and a sharp click sounded behind me.', 'translation': 'Birdenbire eşiğin üzerine bir gölge düştü ve arkamda keskin bir klik sesi duyuldu.', 'notes': 'threshold: eşik.'}, {'id': 391, 'text': '"It is a lovely evening, my dear Watson," said a calm, well-known voice.', 'translation': '"Harika bir akşam, sevgili Watson," dedi sakin, son derece tanıdık bir ses.', 'notes': 'well-known voice: tanıdık ses.'}, {'id': 392, 'text': 'I spun around in astonishment, and there, sitting on a granite rock, was Sherlock Holmes!', 'translation': "Hayretle arkama döndüm ve orada, granit bir kayanın üzerinde oturan kişi Sherlock Holmes'tu!", 'notes': 'spun around: fırıl fırıl döndü.'}, {'id': 393, 'text': '"Holmes!" I cried. "Good heavens! Is it really you?"', 'translation': '"Holmes!" diye haykırdım. "Aman Tanrım! Sahiden sen misin?"', 'notes': 'is it really you: sahiden sen misin?'}, {'id': 394, 'text': '"None other, Watson! And I must congratulate you on your excellent, detailed reports,"', 'translation': '"Başkası değil Watson! Ve mükemmel, ayrıntılı raporların için seni tebrik etmeliyim,"', 'notes': 'none other: ta kendisi, başkası değil.'}, {'id': 395, 'text': '"Cartwright has been bringing your letters and my food from the village every day."', 'translation': '"Cartwright mektuplarını ve yiyeceğimi köyden her gün bana getiriyordu."', 'notes': 'has been bringing: getirmekteydi.'}, {'id': 396, 'text': '"Why did you deceive me, Holmes? Why did you stay in hiding?" I asked, hurt by his secrecy.', 'translation': '"Beni neden aldattın Holmes? Neden saklandın?" diye sordum gizliliğinden incinmiş olarak.', 'notes': 'deceive: kandırmak, aldatmak.'}, {'id': 397, 'text': '"Had you known I was here, our enemies would have guessed it from your natural behaviour,"', 'translation': '"Burada olduğumu bilseydin, düşmanlarımız bunu senin doğal davranışlarından hemen anlarlardı,"', 'notes': 'had you known: bilmiş olsaydın (Type 3 Inversion).'}, {'id': 398, 'text': '"By remaining in the dark, I have uncovered almost the entire conspiracy."', 'translation': '"Karanlıkta gizli kalarak kumpasın neredeyse tamamını gün yüzüne çıkardım."', 'notes': 'conspiracy: komplo, kumpas.'}, {'id': 399, 'text': '"Watson, that charming lady is not Stapleton\'s sister; she is his legal wife!"', 'translation': '"Watson, o büyüleyici hanım Stapleton\'ın kız kardeşi değil; onun nikahlı karısı!"', 'notes': 'legal wife: resmi/nikahlı eş.'}, {'id': 400, 'text': '"He passes her off as his sister so she can lure wealthy men into his deadly traps!"', 'translation': '"Onu kız kardeşi gibi yutturuyor ki zengin adamları kendi ölümcül tuzaklarına çekebilsin!"', 'notes': 'passes off as: gibi yutturmak.'}]}, {'page_no': 21, 'title': 'The Clue in the Family Portrait', 'tr_title': "Aile Portresindeki İpucu: Hugo Baskerville'ın İkizi Stapleton", 'vocab_focus': [('portrait', 'portre, yağlıboya tablo'), ('resemblance', 'benzerlik'), ('cavalier', 'süvari, asilzade'), ('scoundrel', 'alçak, rezil herif'), ('heir', 'mirasçı, varis'), ('conceal', 'gizlemek, saklamak'), ('genealogy', 'soybilim, şecere'), ('unmask', 'maskesini düşürmek')], 'sentences': [{'id': 401, 'text': 'Before Holmes and I could finish our conversation in the hut, a horrifying scream broke the night.', 'translation': 'Kulübedeki sohbetimizi bitiremeden, gecenin sessizliğini dehşet verici bir çığlık yırttı.', 'notes': 'horrifying scream: korkunç çığlık.'}, {'id': 402, 'text': 'It was followed by the deep, resonant baying of an enormous hound hunting upon the moor.', 'translation': 'Ardından bataklıkta avlanan devasa bir tazının derin, gümbürdeyen uluması duyuldu.', 'notes': 'baying: tazı uluması.'}, {'id': 403, 'text': 'We dashed toward the sound and found a broken body lying at the foot of a granite cliff.', 'translation': 'Sese doğru fırladık ve granit bir uçurumun dibinde yatan parçalanmış bir ceset bulduk.', 'notes': 'dashed toward: doğru fırladı.'}, {'id': 404, 'text': 'For a terrible moment we thought it was Sir Henry, because the dead man was dressed in his clothes.', 'translation': 'Korkunç bir an için ölenin Sir Henry olduğunu sandık, çünkü ölü adam onun kıyafetlerini giymişti.', 'notes': 'dressed in: giyinmiş.'}, {'id': 405, 'text': 'Turning the face to the moonlight, Holmes sighed with immense relief: it was Selden the convict!', 'translation': "Yüzü ay ışığına çeviren Holmes derin bir rahatlamayla iç çekti: ölen kişi mahkum Selden'dı!", 'notes': 'immense relief: muazzam rahatlama.'}, {'id': 406, 'text': "Barrymore had given Sir Henry's old cast-off clothes to the starving fugitive.", 'translation': "Barrymore, Sir Henry'nin eski giysilerini açlık çeken bu kaçağa vermişti.", 'notes': 'cast-off: eskimiş/bağışlanmış kıyafet.'}, {'id': 407, 'text': "The hound had hunted him by the scent upon Sir Henry's stolen old boot and driven him over the rocks.", 'translation': "Tazı, Sir Henry'nin çalınan eski çizmesindeki koku sayesinde onu avlamış ve kayalardan aşağı yuvarlamıştı.", 'notes': 'hunted by scent: kokuyla avladı.'}, {'id': 408, 'text': 'Stapleton suddenly emerged from the darkness, expecting to find the dead body of Sir Henry.', 'translation': "Stapleton karanlıktan ansızın çıkageldi; yerde Sir Henry'nin cansız bedenini bulmayı umuyordu.", 'notes': 'expecting to find: bulmayı umarak.'}, {'id': 409, 'text': 'When he saw Holmes and the body of the convict, his face masked his sickening disappointment.', 'translation': "Holmes'u ve mahkumun cesedini gördüğünde yüzü yaşadığı mide bulandırıcı hayal kırıklığını gizlemeye çalıştı.", 'notes': 'sickening disappointment: mide bulandırıcı hayal kırıklığı.'}, {'id': 410, 'text': 'We returned to Baskerville Hall, where Sir Henry welcomed Holmes with overjoyed surprise.', 'translation': "Baskerville Malikanesi'ne döndük; Sir Henry, Holmes'u büyük bir sevinç ve şaşkınlıkla karşıladı.", 'notes': 'overjoyed surprise: aşırı sevinçli şaşkınlık.'}, {'id': 411, 'text': 'During dinner, Holmes suddenly stopped speaking and stared fixedly at the wall above my head.', 'translation': 'Akşam yemeği sırasında Holmes aniden konuşmayı kesti ve başımın üzerindeki duvara pürdikkat bakakaldı.', 'notes': 'stared fixedly: gözünü dikip hareketsiz baktı.'}, {'id': 412, 'text': 'He was gazing at the ancient portrait of Hugo Baskerville, the wicked ancestor of the legend.', 'translation': "Efsanedeki kötü kalpli ata Hugo Baskerville'in asırlık portresine bakıyordu.", 'notes': 'wicked ancestor: uğursuz ata.'}, {'id': 413, 'text': 'After dinner, when Sir Henry had retired, Holmes brought a candle to the canvas.', 'translation': 'Yemekten sonra Sir Henry odasına çekilince Holmes tuvalin yanına bir mum getirdi.', 'notes': 'retired: yatmaya çekilince.'}, {'id': 414, 'text': 'He covered the wide brim of the hat, the long hair, and the lace collar with his hands.', 'translation': 'Elleriyle şapkanın geniş siperini, uzun saçları ve dantel yakayı kapattı.', 'notes': 'wide brim: geniş siper.'}, {'id': 415, 'text': '"Good heavens!" I cried in utter amazement. "It is the exact face of Jack Stapleton!"', 'translation': '"Aman Tanrım!" diye haykırdım mutlak bir hayretle. "Birebir Jack Stapleton\'ın yüzü bu!"', 'notes': 'exact face: birebir aynı yüz.'}, {'id': 416, 'text': '"Yes!" said Holmes quietly. "It is an extraordinary instance of family atavism, both physical and moral."', 'translation': '"Evet!" dedi Holmes sakince. "Hem fiziksel hem ahlaki açıdan olağanüstü bir ailevi atavizm örneği."', 'notes': 'atavism: atalara çekme, soyaçekim.'}, {'id': 417, 'text': '"Stapleton is a Baskerville! He is the son of Rodger Baskerville, Sir Charles\'s younger brother!"', 'translation': '"Stapleton bir Baskerville! Sir Charles\'ın küçük erkek kardeşi Rodger Baskerville\'in oğlu!"', 'notes': 'younger brother: küçük erkek kardeş.'}, {'id': 418, 'text': '"Rodger was believed to have died unmarried in South America, but he left this cunning son."', 'translation': '"Rodger\'ın Güney Amerika\'da bekar öldüğü sanılıyordu, fakat ardında bu kurnaz oğlu bıraktı."', 'notes': 'believed to have died: öldüğüne inanılıyordu.'}, {'id': 419, 'text': '"If Sir Charles and Sir Henry die, this villain inherits the entire title and vast fortune!"', 'translation': '"Eğer Sir Charles ve Sir Henry ölürse, bu alçak bütün unvanı ve dev serveti miras alıyor!"', 'notes': 'inherits the title: unvanı devralır.'}, {'id': 420, 'text': '"Tomorrow evening at Merripit House, he plans to strike his final blow!"', 'translation': '"Yarın akşam Merripit Evi\'nde son darbesini indirmeyi planlıyor!"', 'notes': 'strike final blow: son darbeyi indirmek.'}]}, {'page_no': 22, 'title': 'The Trap at Merripit House', 'tr_title': "Merripit House'daki Ölümcül Tuzak ve Çöken Yoğun Sis", 'vocab_focus': [('ambush', 'pusu'), ('fog', 'yoğun sis'), ('drift', 'ağır ağır sürüklenmek'), ('perilous', 'çok tehlikeli'), ('shadow', 'gölge'), ('anxiety', 'endişe, kaygı'), ('revolver', 'altıpatlar'), ('creeping', 'yavaşça sokulan, sürünen')], 'sentences': [{'id': 421, 'text': "Holmes instructed Sir Henry to accept Stapleton's invitation to dinner at Merripit House alone.", 'translation': "Holmes, Sir Henry'ye Stapleton'ın Merripit Evi'ndeki akşam yemeği davetini tek başına kabul etmesini söyledi.", 'notes': 'instructed: talimat verdi.'}, {'id': 422, 'text': '"Tell him that Watson and I have returned to London on urgent business," Holmes commanded.', 'translation': '"Ona Watson ile benim acil bir iş için Londra\'ya döndüğümüzü söyle," diye emretti Holmes.', 'notes': 'commanded: emretti.'}, {'id': 423, 'text': '"And whatever happens, promise me that you will walk back to Baskerville Hall across the moor alone."', 'translation': '"Ve her ne olursa olsun, Baskerville Malikanesi\'ne bataklıktan tek başına yürüyeceğine bana söz ver."', 'notes': 'promise me: bana söz ver.'}, {'id': 424, 'text': "Sir Henry looked startled, but placed absolute trust in Holmes's supreme intellect.", 'translation': "Sir Henry irkildi, fakat Holmes'un üstün zekasına mutlak bir güven besledi.", 'notes': 'supreme intellect: üstün akıl/zeka.'}, {'id': 425, 'text': 'Meanwhile, Holmes telegraphed London to summon Inspector Lestrade from Scotland Yard.', 'translation': "Bu sırada Holmes, Scotland Yard'dan Müfettiş Lestrade'ı çağırmak üzere Londra'ya telgraf çekti.", 'notes': 'summon: çağırmak, celbetmek.'}, {'id': 426, 'text': "Lestrade arrived on the afternoon train, armed with a legal warrant for Stapleton's arrest.", 'translation': "Lestrade öğleden sonraki trenle, Stapleton'ın tutuklanmasına dair resmi bir yakalama emriyle geldi.", 'notes': 'legal warrant: yasal yakalama müzekkeresi.'}, {'id': 427, 'text': 'As darkness fell, Holmes, Lestrade, and I crept across the heather toward Merripit House.', 'translation': "Karanlık çökerken Holmes, Lestrade ve ben fundalıkların üzerinden Merripit Evi'ne doğru sessizce yaklaştık.", 'notes': 'as darkness fell: karanlık çökerken.'}, {'id': 428, 'text': 'We concealed ourselves behind a row of rocks fifty yards from the lighted dining-room window.', 'translation': 'Aydınlatılmış yemek odası penceresinden elli yarda uzaktaki bir kayalık dizisinin arkasına gizlendik.', 'notes': 'concealed ourselves: gizlendik.'}, {'id': 429, 'text': 'Peering through the glass, we saw Sir Henry and Stapleton smoking cigars and chatting over coffee.', 'translation': "Camdan baktığımızda Sir Henry ve Stapleton'ı puro içip kahve eşliğinde sohbet ederken gördük.", 'notes': 'peering through: camdan bakarak.'}, {'id': 430, 'text': 'Miss Stapleton was nowhere to be seen in the house.', 'translation': 'Matmazel Stapleton evin hiçbir yerinde görünmüyordu.', 'notes': 'nowhere to be seen: hiçbir yerde görünmüyor.'}, {'id': 431, 'text': 'Presently, Stapleton rose, slipped outside to an outhouse in the yard, and returned after two minutes.', 'translation': 'Çok geçmeden Stapleton kalktı, bahçedeki bir müştemilata sıvıştı ve iki dakika sonra geri döndü.', 'notes': 'outhouse: müştemilat, dış bina.'}, {'id': 432, 'text': '"He is preparing the beast!" Holmes whispered with intense excitement.', 'translation': '"Yaratığı hazırlıyor!" diye fısıldadı Holmes büyük bir heyecanla.', 'notes': 'preparing the beast: canavarı hazırlıyor.'}, {'id': 433, 'text': 'Suddenly, a thick, white fog bank rolled out from the Great Grimpen Mire.', 'translation': "Birdenbire Büyük Grimpen Bataklığı'ndan kalın, beyaz bir sis tabakası yuvarlanarak geldi.", 'notes': 'fog bank: sis tabakası / bulutu.'}, {'id': 434, 'text': 'It moved like a living white tide, creeping silently over the heather toward the path.', 'translation': 'Canlı beyaz bir medcezir gibi ilerliyor, patikaya doğru fundalıkların üzerinden sessizce sokuluyordu.', 'notes': 'living white tide: canlı beyaz medcezir.'}, {'id': 435, 'text': '"The fog!" Holmes gasped, clenching his fists in acute dismay.', 'translation': '"Sis!" diye nefesi kesildi Holmes\'un; büyük bir dehşet içinde yumruklarını sıkarak.', 'notes': 'acute dismay: şiddetli dehşet.'}, {'id': 436, 'text': '"If it covers the path, we will not be able to see him or shoot the hound!"', 'translation': '"Eğer patikayı kapatırsa, ne onu görebileceğiz ne de köpeği vurabileceğiz!"', 'notes': 'shoot the hound: köpeği vurmak.'}, {'id': 437, 'text': '"In ten minutes, our field of view will be completely blinded!"', 'translation': '"On dakika içinde görüş alanımız tamamen kör olacak!"', 'notes': 'field of view: görüş alanı.'}, {'id': 438, 'text': 'The front door of Merripit House opened, and Sir Henry walked out into the cold night.', 'translation': "Merripit Evi'nin ön kapısı açıldı ve Sir Henry soğuk geceye adım attı.", 'notes': 'walked out: dışarı çıktı.'}, {'id': 439, 'text': 'He looked up at the clearing sky, pulled his collar high, and set off along the moor path.', 'translation': 'Açılan gökyüzüne baktı, yakasını kaldırdı ve bataklık patikası boyunca yürümeye başladı.', 'notes': 'set off along: boyunca yola koyuldu.'}, {'id': 440, 'text': 'He was walking straight into the deadly trap prepared for his destruction.', 'translation': 'Kendi yok oluşu için hazırlanmış o ölümcül tuzağa doğru dosdoğru yürüyordu.', 'notes': 'straight into: dosdoğru içine.'}]}, {'page_no': 23, 'title': 'The Hound Unleashed and the Phosphorus Fire', 'tr_title': "Alev Saçan Dev Tazının Saldırısı ve Holmes'un Kurşunları", 'vocab_focus': [('monstrous', 'canavarımsı, korkunç'), ('phosphorus', 'fosfor, ışıldayan madde'), ('flame', 'alev'), ('muzzle', 'namlu / hayvanın ağız-burun kısmı'), ('gallop', 'dörtnala koşmak'), ('chamber', 'tabanca mermi yuvası'), ('paralyzed', 'felç olmuş, donakalmış'), ('agony', 'can çekişme, can havli')], 'sentences': [{'id': 441, 'text': 'Sir Henry passed our hiding place and disappeared into the creeping wall of white fog.', 'translation': 'Sir Henry saklandığımız yerin önünden geçti ve sürünen beyaz sis duvarının içinde kayboldu.', 'notes': 'creeping wall: yaklaşan duvar.'}, {'id': 442, 'text': 'Then, from the heart of the mist, came a swift, rhythmic pitter-patter of bounding paws.', 'translation': 'Ardından sisin kalbinden, sıçrayan patilerin hızlı, ritmik pıtır pıtır sesleri geldi.', 'notes': 'pitter-patter: pıtır pıtır ayak sesleri.'}, {'id': 443, 'text': 'Out of the fog leaped a monstrous creature, black as coal, but glowing with hellish fire.', 'translation': 'Sisin içinden kömür kadar kara, fakat cehennemi bir ateşle parıldayan canavarımsı bir yaratık fırladı.', 'notes': 'leaped: fırladı, sıçradı.'}, {'id': 444, 'text': 'Fire burst from its open mouth, its deep-set eyes glowed like smouldering coals, and its muzzle flickered with bluish flame.', 'translation': 'Açık ağzından ateş püskürüyor, çukur gözleri kor gibi parlıyor ve burnu mavimsi alevlerle titreşiyordu.', 'notes': 'smouldering coals: için için yanan kömürler.'}, {'id': 445, 'text': 'Never in a nightmare had human mind conceived anything more terrifying or horrific.', 'translation': 'Hiçbir kabusta insan aklı bundan daha korkunç ve dehşet verici bir şey tasavvur edemezdi.', 'notes': 'conceived: tasavvur etmişti.'}, {'id': 446, 'text': 'Lestrade gave a shriek of terror and hurled himself flat upon the ground.', 'translation': 'Lestrade bir dehşet çığlığı attı ve kendini yüzüstü yere fırlattı.', 'notes': 'hurled flat: yüzüstü yere kapandı.'}, {'id': 447, 'text': 'The huge hound bounding down the track was a bloodhound-mastiff hybrid, gigantic and savage.', 'translation': 'Yolda dörtnala sıçrayan koca tazı; devasa ve vahşi bir tazı-mastif kırmasıydı.', 'notes': 'hybrid: kırma, melez.'}, {'id': 448, 'text': 'Holmes and I fired our revolvers together, the shots echoing like thunder over the moor.', 'translation': 'Holmes ve ben tabancalarımızı aynı anda ateşledik; kurşunlar bataklıkta gök gürültüsü gibi yankılandı.', 'notes': 'echoing like thunder: gök gürültüsü gibi yankılanan.'}, {'id': 449, 'text': 'The beast gave a hideous howl of pain, proving that it was flesh and blood, not a phantom.', 'translation': 'Yaratık acı dolu korkunç bir feryat kopardı; bu da onun bir hayalet değil, etten ve kemikten olduğunu kanıtladı.', 'notes': 'flesh and blood: etten ve kemikten.'}, {'id': 450, 'text': 'Yet the bullet did not halt it; it continued bounding at incredible speed toward Sir Henry.', 'translation': "Yine de mermi onu durduramadı; Sir Henry'ye doğru inanılmaz bir hızla sıçramayı sürdürdü.", 'notes': 'bounding: sıçrayarak koşmak.'}, {'id': 451, 'text': 'We leaped over the rocks and sprinted through the fog as fast as our legs could carry us.', 'translation': 'Kayaların üzerinden atladık ve bacaklarımızın bizi taşıyabileceği en yüksek hızla sisin içine koştuk.', 'notes': 'sprinted: son sürat koştu.'}, {'id': 452, 'text': 'Ahead, we saw Sir Henry turn round, paralyzed with fright at the glowing apparition.', 'translation': "İleride Sir Henry'nin arkasına döndüğünü, ışık saçan bu hortlak karşısında korkudan donakaldığını gördük.", 'notes': 'paralyzed with fright: korkudan felç olmuş.'}, {'id': 453, 'text': 'The monstrous beast sprang into the air and bore the baronet straight down to the turf.', 'translation': 'Canavarımsı hayvan havaya sıçradı ve baroneti dosdoğru çimlerin üzerine devirdi.', 'notes': 'bore straight down: yere devirdi.'}, {'id': 454, 'text': "Its glowing jaws snapped toward the young man's unprotected throat.", 'translation': 'Alev saçan çeneleri genç adamın korumasız gırtlağına doğru kenetlenmek üzere kapandı.', 'notes': 'unprotected throat: korumasız gırtlak.'}, {'id': 455, 'text': "In that final second, Holmes emptied five chambers of his revolver straight into the creature's flank.", 'translation': 'O son saniyede Holmes, tabancasındaki beş mermiyi yaratığın böğrüne peş peşe boşalttı.', 'notes': 'emptied chambers: mermileri boşalttı.'}, {'id': 456, 'text': 'With a dreadful shriek of agony, the giant hound rolled onto its back, clawing wildly at the air.', 'translation': 'Korkunç bir can çekişme çığlığıyla dev tazı sırtüstü yuvarlandı, havayı delicesine pençeledi.', 'notes': 'clawing wildly: vahşice pençe atarak.'}, {'id': 457, 'text': 'It snapped its teeth once more, shuddered violently, and fell lifeless upon the grass.', 'translation': 'Dişlerini son bir kez birbirine çarptı, şiddetle titredi ve otların üzerine cansız serildi.', 'notes': 'fell lifeless: cansız yere düştü.'}, {'id': 458, 'text': 'Sir Henry lay unconscious beneath it, fainting from sheer shock and exhaustion.', 'translation': 'Sir Henry onun altında bilincini yitirmiş halde yatıyordu; katıksız bir şok ve bitkinlikten bayılmıştı.', 'notes': 'fainting: bayılarak.'}, {'id': 459, 'text': 'Holmes touched the muzzle of the dead beast and sniffed his glowing fingers.', 'translation': 'Holmes ölü hayvanın burnuna dokundu ve parıldayan parmaklarını kokladı.', 'notes': 'sniffed: kokladı.'}, {'id': 460, 'text': '"A cunning chemical preparation of phosphorus!" cried Holmes. "Luminous, but odorless and harmless to the dog!"', 'translation': '"Kurnazca hazırlanmış bir fosfor kimyasal karışımı!" diye haykırdı Holmes. "Işık saçıyor ama kokusuz ve köpeğe zararsız!"', 'notes': 'chemical preparation: kimyasal terkip.'}]}, {'page_no': 24, 'title': 'Searching Merripit House and the Fate of Stapleton', 'tr_title': "Merripit House'un Aranması ve Stapleton'ın Bataklıktaki Sonu", 'vocab_focus': [('bound', 'bağlanmış, kilitli'), ('gagged', 'ağzı tıkanmış/bağlanmış'), ('cruelty', 'zalimlik, gaddarlık'), ('quicksand', 'bataklık kumu'), ('submerge', 'tamamen batmak/gömülmek'), ('footprint', 'ayak izi'), ('perish', 'yok olmak, can vermek'), ('skeleton', 'iskelet')], 'sentences': [{'id': 461, 'text': 'We revived Sir Henry with a sip of brandy from my flask and ensured he was unhurt.', 'translation': "Sir Henry'yi mataramdaki konyaktan bir yudumla ayıltıp hiçbir yara almadığından emin olduk.", 'notes': 'revived: ayılttık.'}, {'id': 462, 'text': '"Now, to Merripit House! We must seize Stapleton before he learns of our victory!" cried Holmes.', 'translation': '"Şimdi doğru Merripit Evi\'ne! Zaferimizden haberdar olmadan önce Stapleton\'ı yakalamalıyız!" diye bağırdı Holmes.', 'notes': 'seize: yakalamak, kıskıvrak ele geçirmek.'}, {'id': 463, 'text': 'We rushed to the house; the front door was open, but every room on the ground floor was dark and deserted.', 'translation': 'Eve koştuk; ön kapı açıktı fakat zemin kattaki her oda karanlık ve terk edilmişti.', 'notes': 'deserted: terk edilmiş.'}, {'id': 464, 'text': 'Upstairs, one bedroom door was locked with a heavy iron key.', 'translation': 'Üst katta bir yatak odasının kapısı ağır bir demir anahtarla kilitlenmişti.', 'notes': 'locked with: ile kilitlenmiş.'}, {'id': 465, 'text': 'Holmes kicked the lock off with his heel, and the door flew wide open.', 'translation': 'Holmes topuğuyla kilidi tekmeleyip kırdı ve kapı sonuna kadar ardına açıldı.', 'notes': 'flew wide open: ardına kadar açıldı.'}, {'id': 466, 'text': 'Inside, tied to a wooden pillar and gagged with a silk scarf, was Mrs. Beryl Stapleton.', 'translation': 'İçeride, ahşap bir sütuna bağlanmış ve ağzı ipek bir atkıyla tıkanmış halde Bayan Beryl Stapleton duruyordu.', 'notes': 'gagged: ağzı tıkanmış.'}, {'id': 467, 'text': 'Cruel bruises upon her bare arms showed that she had endured brutal ill-treatment.', 'translation': 'Çıplak kollarındaki acımasız morluklar, gaddarca bir kötü muameleye maruz kaldığını gösteriyordu.', 'notes': 'bruises: morluklar, bereler.'}, {'id': 468, 'text': 'Holmes quickly cut the cords and removed the gag from her mouth.', 'translation': 'Holmes hızla ipleri kesti ve kadının ağzındaki bağı çıkardı.', 'notes': 'cut the cords: ipleri kesti.'}, {'id': 469, 'text': '"Is Sir Henry safe? Did he escape?" she cried out, her first thought being of the young baronet.', 'translation': '"Sir Henry güvende mi? Kurtuldu mu?" diye haykırdı; ilk aklına gelen genç baronet olmuştu.', 'notes': 'is he safe: güvende mi?'}, {'id': 470, 'text': '"He is safe, and the hound is dead!" Holmes assured her gently.', 'translation': '"O güvende ve tazı öldü!" diye temin etti Holmes kibarca.', 'notes': 'assured gently: kibarca temin etti.'}, {'id': 471, 'text': '"Thank God!" she wept. "When I refused to help his murderous scheme tonight, he beat me and bound me here!"', 'translation': '"Tanrı\'ya şükürler olsun!" diye ağladı. "Bu gece onun o cani planına yardım etmeyi reddedince beni dövdü ve buraya bağladı!"', 'notes': 'murderous scheme: caniyane plan.'}, {'id': 472, 'text': '"Where has he fled? Where can we find him?" Holmes demanded urgently.', 'translation': '"Nereye kaçtı? Onu nerede bulabiliriz?" diye acilen sordu Holmes.', 'notes': 'where has he fled: nereye kaçtı.'}, {'id': 473, 'text': '"There is only one place: an island in the heart of the Grimpen Mire, where he kept the hound in an old tin mine!"', 'translation': '"Yalnızca tek bir yer var: Grimpen Bataklığı\'nın kalbinde, köpeği eski bir kalay madeninde sakladığı ada!"', 'notes': 'tin mine: kalay madeni.'}, {'id': 474, 'text': '"He set small markers along the secret path to guide his way through the quicksand."', 'translation': '"Bataklıkta yolunu bulabilmek için gizli patika boyunca küçük işaretler koymuştu."', 'notes': 'set markers: işaretler koydu.'}, {'id': 475, 'text': 'The next morning, guided by Mrs. Stapleton, we set out into the treacherous morass.', 'translation': "Ertesi sabah Bayan Stapleton'ın rehberliğinde tekinsiz bataklığa doğru yola koyulduk.", 'notes': 'guided by: rehberliğinde.'}, {'id': 476, 'text': 'Along the boggy path, we found small sticks driven into the peat as guide-posts.', 'translation': 'Bataklık patika boyunca kılavuz direkleri olarak turbaya saplanmış küçük sopalar bulduk.', 'notes': 'guide-posts: yön direkleri.'}, {'id': 477, 'text': 'Halfway to the island, Holmes spotted something black protruding from the green slime.', 'translation': 'Adaya giden yolun yarısında Holmes yeşil balçıktan dışarı fırlamış siyah bir şey fark etti.', 'notes': 'protruding: dışarı fırlamış / çıkmış.'}, {'id': 478, 'text': "He pulled it out with difficulty: it was Sir Henry's stolen old black boot!", 'translation': "Onu güçlükle çekip çıkardı: Sir Henry'nin çalınan eski siyah çizmesiydi bu!", 'notes': 'pulled it out: çekip çıkardı.'}, {'id': 479, 'text': "Beyond that point, the markers ended; the dense fog of the previous night had blinded the fugitive's eyes.", 'translation': 'O noktanın ötesinde işaretler sona eriyordu; önceki gecenin yoğun sisi kaçağın gözlerini kör etmişti.', 'notes': 'beyond that point: o noktadan öteye.'}, {'id': 480, 'text': 'Stapleton had stepped off the narrow path and been swallowed alive by the bottomless mud of the Grimpen Mire.', 'translation': "Stapleton daracık patikadan sapmış ve Grimpen Bataklığı'nın dipsiz çamuru tarafından diri diri yutulmuştu.", 'notes': 'swallowed alive: canlı canlı yutuldu.'}]}, {'page_no': 25, 'title': 'Holmes Explains the Masterpiece of Crime', 'tr_title': "Baker Sokağı'nda Holmes'un Şeytani Planın Sırlarını Çözüşü", 'vocab_focus': [('retrospect', 'geçmişe bakış, geriye dönük inceleme'), ('accomplice', 'suç ortağı'), ('phosphorus', 'fosfor'), ('heir', 'mirasçı'), ('cunning', 'kurnazlık, sinsilik'), ('ingenious', 'dahiyane, ustalıklı'), ('reign', 'hüküm sürme'), ('masterpiece', 'başyapıt')], 'sentences': [{'id': 481, 'text': 'It was the end of November, and Holmes and I sat together by a crackling fire at Baker Street.', 'translation': "Kasım ayının sonuydu ve Holmes ile ben Baker Sokağı'nda çıtırdayan bir ateşin başında oturuyorduk.", 'notes': 'crackling fire: çıtırdayan ateş.'}, {'id': 482, 'text': "Sir Henry and Dr. Mortimer had departed on a sea voyage around the world to restore the baronet's nerves.", 'translation': 'Sir Henry ve Dr. Mortimer, baronetın yıpranan sinirlerini toparlamak için dünya turu niteliğinde bir deniz yolculuğuna çıkmışlardı.', 'notes': 'sea voyage: deniz yolculuğu.'}, {'id': 483, 'text': '"Now, Holmes, explain to me the complete details of that dark and intricate drama," I asked.', 'translation': '"Şimdi Holmes, o karanlık ve karmaşık dramanın tüm ayrıntılarını bana açıkla," dedim.', 'notes': 'intricate drama: karmaşık dram/olay.'}, {'id': 484, 'text': 'Holmes drew deeply on his favourite pipe and watched the blue smoke coil toward the ceiling.', 'translation': 'Holmes en sevdiği piposundan derin bir nefes çekti ve tavana doğru kıvrılan mavi dumanı izledi.', 'notes': 'coil: kıvrılarak yükselmek.'}, {'id': 485, 'text': '"Stapleton was a man of extraordinary intellectual gifts and boundless criminal audacity," began Holmes.', 'translation': '"Stapleton olağanüstü zihinsel yeteneklere ve sınırsız bir cürete sahip bir suçluydu," diye başladı Holmes.', 'notes': 'boundless audacity: sınırsız cüret.'}, {'id': 486, 'text': '"In South America, he married Beryl Garcia, a beautiful Costa Rican woman."', 'translation': '"Güney Amerika\'da Kosta Rikalı güzel bir kadın olan Beryl Garcia ile evlenmişti."', 'notes': 'married: evlendi.'}, {'id': 487, 'text': '"Having stolen public funds, he changed his name and opened a school in Yorkshire, which failed."', 'translation': '"Kamu paralarını çaldıktan sonra adını değiştirip Yorkshire\'da bir okul açmış, fakat iflas etmişti."', 'notes': 'having stolen: çaldıktan sonra (Perfect Participle).'}, {'id': 488, 'text': '"He then discovered that only two lives stood between him and the immense Baskerville fortune."', 'translation': '"Ardından kendisi ile devasa Baskerville serveti arasında yalnızca iki canın durduğunu keşfetti."', 'notes': 'stood between: arasında duruyordu.'}, {'id': 489, 'text': '"He moved to Dartmoor, posing as a naturalist, and learned the ancient legend of the demon hound."', 'translation': '"Bir doğa bilimci kılığına girerek Dartmoor\'a taşındı ve iblis tazı hakkındaki kadim efsaneyi öğrendi."', 'notes': 'posing as: ... rolü yaparak.'}, {'id': 490, 'text': '"He purchased a gigantic mastiff-bloodhound cross in London and concealed it in the Grimpen Mire."', 'translation': '"Londra\'dan devasa bir mastif-tazı kırması satın aldı ve onu Grimpen Bataklığı\'nda sakladı."', 'notes': 'purchased: satın aldı.'}, {'id': 491, 'text': '"Knowing Sir Charles\'s heart condition and superstitious dread, he used Mrs. Laura Lyons to lure him to the gate."', 'translation': '"Sir Charles\'ın kalp rahatsızlığını ve batıl korkusunu bildiğinden, onu kapıya çekmek için Laura Lyons\'ı kullandı."', 'notes': 'lure to the gate: kapıya çekmek / yemlemek.'}, {'id': 492, 'text': '"When the phosphorus-coated beast burst upon the old man in the dark, sheer terror stopped his heart."', 'translation': '"Karanlıkta fosfor kaplı canavar yaşlı adamın üzerine fırladığında, katıksız bir dehşet onun kalbini durdurdu."', 'notes': 'stopped his heart: kalbini durdurdu.'}, {'id': 493, 'text': '"When Sir Henry arrived in London, Stapleton followed him in the cab, wearing a false beard."', 'translation': '"Sir Henry Londra\'ya vardığında Stapleton takma bir sakal takarak onu faytonla izledi."', 'notes': 'wearing a false beard: takma sakal takarak.'}, {'id': 494, 'text': '"His wife secretly pasted together that warning note from The Times to save the young man\'s life."', 'translation': '"Karısı, genç adamın hayatını kurtarmak için The Times\'tan o uyarı notunu gizlice yapıştırıp hazırladı."', 'notes': 'pasted together: yapıştırarak hazırladı.'}, {'id': 495, 'text': '"Stapleton bribed a hotel servant to steal an old boot so his hound could follow Sir Henry\'s individual scent."', 'translation': '"Stapleton, tazısının Sir Henry\'nin kendine has kokusunu takip edebilmesi için eski bir çizmeyi çalması amacıyla otel hizmetkarına rüşvet verdi."', 'notes': 'individual scent: bireysel/özel koku.'}, {'id': 496, 'text': '"How would he have claimed the estate without raising suspicion?" I asked.', 'translation': '"Şüphe uyandırmadan malikaneyi nasıl talep edecekti peki?" diye sordum.', 'notes': 'without raising suspicion: şüphe uyandırmadan.'}, {'id': 497, 'text': '"He would have claimed it from South America through British consuls, or lived upon the money under an assumed identity."', 'translation': '"Güney Amerika\'dan İngiliz konsoloslukları aracılığıyla talep edebilir ya da sahte bir kimlikle bu serveti afiyetle yiyebilirdi."', 'notes': 'assumed identity: sahte kimlik.'}, {'id': 498, 'text': '"He was a master criminal, but like all wicked men, he was finally destroyed by his own evil web."', 'translation': '"O usta bir suçluydu; fakat tüm kötü adamlar gibi en nihayetinde kendi kötülük ağı tarafından yok edildi."', 'notes': 'evil web: kötülük ağı.'}, {'id': 499, 'text': '"And now, Watson, we have examined enough horrors for one winter; put on your coat."', 'translation': '"Ve şimdi Watson, bir kış mevsimi için yeterince dehşet inceledik; paltonu giy bakalım."', 'notes': 'put on: giyinmek.'}, {'id': 500, 'text': '"There is a box reserved for us at the Opera, and the music will clear our minds of the Grimpen Mire."', 'translation': '"Operada bizim için ayrılmış bir loca var ve bu müzik zihnimizi Grimpen Bataklığı\'ndan arındıracaktır."', 'notes': 'clear our minds: zihnimizi temizlemek.'}]}]
